css:
.fxg-streams {
  /* Re-theme with these three; plate, rules and tints are derived. */
  --fxg-streams-paper: oklch(0.962 0.014 84);
  --fxg-streams-ink: oklch(0.255 0.03 48);
  --fxg-streams-accent: oklch(0.6 0.19 33);

  --fxg-streams-plate: color-mix(in oklch, var(--fxg-streams-paper) 55%, oklch(0.995 0.004 90));
  --fxg-streams-muted: color-mix(in oklch, var(--fxg-streams-ink) 58%, var(--fxg-streams-paper));
  --fxg-streams-line: color-mix(in oklch, var(--fxg-streams-ink) 14%, transparent);
  --fxg-streams-wash: color-mix(in oklch, var(--fxg-streams-accent) 12%, var(--fxg-streams-paper));
  --fxg-streams-out: cubic-bezier(.16, 1, .3, 1);
  --fxg-streams-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" "plate plate" "bar bar";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 10px 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 10 / 9;
  min-block-size: 300px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxg-streams-paper);
  color: var(--fxg-streams-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxg-streams-line);

  & .fxg-streams__head { grid-area: head; min-inline-size: 0; }
  & .fxg-streams__eyebrow {
    display: flex;
    gap: 6px;
    margin: 0 0 3px;
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-streams-muted);
  }
  & .fxg-streams__eyebrow span {
    font: 500 9.5px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .02em;
    font-variant-numeric: tabular-nums;
    color: var(--fxg-streams-accent);
  }
  & .fxg-streams__title {
    margin: 0;
    font-size: clamp(19px, 6.4cqi, 27px);
    font-weight: 700;
    line-height: 1;
    letter-spacing: -0.03em;
    text-wrap: balance;
  }
  & .fxg-streams__read {
    grid-area: read;
    display: flex;
    gap: 14px;
    align-self: end;
    margin: 0;
  }
  & .fxg-streams__read div {
    display: grid;
    gap: 3px;
    text-align: end;
    transition: opacity .6s var(--fxg-streams-out) calc(var(--i) * 70ms + 120ms), translate .8s var(--fxg-streams-out) calc(var(--i) * 70ms + 120ms);
    @starting-style { opacity: 0; translate: 0 5px; }
  }
  & .fxg-streams__read dt {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-streams-muted);
  }
  & .fxg-streams__read dd {
    margin: 0;
    font: 600 clamp(13px, 4cqi, 16px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxg-streams__read small { margin-inline-start: 2px; font-size: .7em; font-weight: 500; color: var(--fxg-streams-muted); }

  & .fxg-streams__plate {
    grid-area: plate;
    position: relative;
    min-block-size: 0;
    border-radius: 3px;
    background: var(--fxg-streams-plate);
    box-shadow: 0 0 0 1px var(--fxg-streams-line), 0 12px 22px -18px color-mix(in oklch, var(--fxg-streams-ink) 60%, transparent);
    overflow: hidden;
  }
  & .fxg-streams__cv,
  & .fxg-streams__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxg-streams__cv { display: block; }
  & .fxg-streams__stage {
    z-index: 1;
    cursor: crosshair;
    outline: none;
    touch-action: manipulation;
  }
  & .fxg-streams__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxg-streams-accent), inset 0 0 0 5px color-mix(in oklch, var(--fxg-streams-accent) 18%, transparent);
  }
  & .fxg-streams__hint,
  & .fxg-streams__keys {
    position: absolute;
    inset-inline-start: 8px;
    inset-block-end: 7px;
    z-index: 2;
    display: flex;
    align-items: center;
    gap: 5px;
    margin: 0;
    padding: 3px 7px 3px 5px;
    border-radius: 999px;
    background: color-mix(in oklch, var(--fxg-streams-plate) 86%, transparent);
    font-size: 10.5px;
    font-weight: 500;
    color: var(--fxg-streams-muted);
    pointer-events: none;
    transition: opacity .45s var(--fxg-streams-out), translate .6s var(--fxg-streams-out);
  }
  & .fxg-streams__hint svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: var(--fxg-streams-accent);
    stroke-width: 1.4;
    stroke-linecap: round;
  }
  & .fxg-streams__keys { opacity: 0; translate: 0 4px; font-size: 10px; }
  & .fxg-streams__keys kbd {
    padding: 1px 4px;
    border-radius: 4px;
    background: var(--fxg-streams-paper);
    box-shadow: inset 0 0 0 1px var(--fxg-streams-line);
    font: 600 9.5px/1.3 ui-monospace, Menlo, monospace;
    color: var(--fxg-streams-ink);
  }
  &:not([data-v="0"]) .fxg-streams__hint { opacity: 0; translate: 0 4px; }
  &[data-v="0"] .fxg-streams__btn b { display: none; }
  &:has(.fxg-streams__stage:focus-visible) .fxg-streams__hint { opacity: 0; }
  &:has(.fxg-streams__stage:focus-visible) .fxg-streams__keys { opacity: 1; translate: 0 0; }

  & .fxg-streams__bar {
    grid-area: bar;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 8px;
  }
  & .fxg-streams__sep {
    display: grid;
    grid-template-columns: auto minmax(40px, 1fr) auto;
    align-items: center;
    gap: 8px;
    min-inline-size: 0;
  }
  & .fxg-streams__name {
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-streams-muted);
  }
  & .fxg-streams__sep input {
    inline-size: 100%;
    margin: 0;
    accent-color: var(--fxg-streams-ink);
    cursor: pointer;
  }
  & .fxg-streams__sep input:focus-visible { outline: 2px solid var(--fxg-streams-accent); outline-offset: 3px; border-radius: 4px; }
  & .fxg-streams__sep output {
    min-inline-size: 5.4ch;
    font: 600 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    text-align: end;
  }
  & .fxg-streams__btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    block-size: 30px;
    padding: 0 11px 0 9px;
    border: 0;
    border-radius: 999px;
    background: transparent;
    box-shadow: inset 0 0 0 1px var(--fxg-streams-line);
    color: var(--fxg-streams-ink);
    font: 600 11.5px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: background-color .25s var(--fxg-streams-out), box-shadow .25s var(--fxg-streams-out), scale .4s var(--fxg-streams-spring), opacity .3s;
  }
  & .fxg-streams__btn:hover:not(:disabled) { background: var(--fxg-streams-wash); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--fxg-streams-accent) 40%, transparent); }
  & .fxg-streams__btn:active:not(:disabled) { scale: .94; }
  & .fxg-streams__btn:disabled { opacity: .42; cursor: default; }
  & .fxg-streams__btn:focus-visible { outline: 2px solid var(--fxg-streams-accent); outline-offset: 2px; }
  & .fxg-streams__btn b {
    min-inline-size: 1.6ch;
    padding: 2px 4px;
    border-radius: 999px;
    background: var(--fxg-streams-accent);
    color: var(--fxg-streams-plate);
    font: 700 9.5px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    text-align: center;
  }
  & .fxg-streams__btn svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxg-streams__btn--go {
    background: var(--fxg-streams-ink);
    box-shadow: none;
    color: var(--fxg-streams-plate);
  }
  & .fxg-streams__btn--go:hover:not(:disabled) {
    background: color-mix(in oklch, var(--fxg-streams-ink) 82%, var(--fxg-streams-accent));
    box-shadow: none;
  }
  & .fxg-streams__btn--go svg { transition: rotate .6s var(--fxg-streams-spring); }
  & .fxg-streams__btn--go:hover svg { rotate: 90deg; }
  & .fxg-streams__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @container (max-width: 340px) {
    & .fxg-streams__name { display: none; }
    & .fxg-streams__btn span { display: none; }
    & .fxg-streams__read { gap: 10px; }
  }
  @container (min-width: 560px) {
    & .fxg-streams__title { font-size: 30px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxg-streams {
    & .fxg-streams__read div,
    & .fxg-streams__hint,
    & .fxg-streams__keys,
    & .fxg-streams__btn,
    & .fxg-streams__btn--go svg { transition: none; }
  }
}

js:
/* Streamlines — Jobard & Lefer (1997), "Creating evenly-spaced streamlines of
   arbitrary density". A line is integrated (RK2) forwards and backwards from a seed
   until it leaves the plate or comes within d_test of a line already drawn; new seeds
   are proposed one separation d_sep to either side of every accepted line, and are
   kept only if nothing is closer than d_sep. A uniform grid of cell d_sep makes every
   distance query a 3x3 look-up. Pen width follows each sample's clearance, so a line
   thins to a hairline exactly where it runs into a neighbour. The field is seeded,
   domain-warped gradient noise plus any Gaussian vortices the viewer drops. */
const plate = root.querySelector('.fxg-streams__plate');
const cv = root.querySelector('.fxg-streams__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxg-streams__stage');
const probe = root.querySelector('.fxg-streams__probe');
const live = root.querySelector('.fxg-streams__sr');
const sepIn = root.querySelector('.fxg-streams__sep input');
const $ = (n) => root.querySelector('[data-k="' + n + '"]');
const outSeed = $('seed'), outLines = $('lines'), outInk = $('ink'), outSep = $('sep'), outV = $('vort');
const btnNew = root.querySelector('[data-act="new"]');
const btnClear = root.querySelector('[data-act="clear"]');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2, MM = 25.4 / 96, MARGIN = 10, STEP = 1.25, MAXSTEP = 1600, MAXV = 5;
let W = 0, H = 0, DPR = 1;
let seed = 2714, noise = null, fld = null;
let dsep = 9, dtest = 4.5;
let lines = [], total = 0;
const vort = [];
let spin = 1;
const pal = {};
const ink = document.createElement('canvas'), ix = ink.getContext('2d');

/* ── colour: resolve any CSS colour (oklch, color-mix, var chains) to sRGB bytes ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
function theme() {
  pal.ink = rgb('--fxg-streams-ink');
  pal.accent = rgb('--fxg-streams-accent');
  pal.plate = rgb('--fxg-streams-plate');
}

/* ── seeded randomness and gradient noise ── */
function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}
function makeNoise(s) {
  const r = rng(s), perm = new Uint8Array(512), gx = new Float32Array(256), gy = new Float32Array(256);
  const p = Array.from({ length: 256 }, (_, i) => i);
  for (let i = 255; i > 0; i--) { const j = (r() * (i + 1)) | 0; const t = p[i]; p[i] = p[j]; p[j] = t; }
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
  for (let i = 0; i < 256; i++) { const a = r() * TAU; gx[i] = Math.cos(a); gy[i] = Math.sin(a); }
  return (x, y) => {
    const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi, X = xi & 255, Y = yi & 255;
    const u = xf * xf * xf * (xf * (xf * 6 - 15) + 10), v = yf * yf * yf * (yf * (yf * 6 - 15) + 10);
    const g = (i, j, dx, dy) => { const h = perm[perm[i] + j]; return gx[h] * dx + gy[h] * dy; };
    const a = g(X, Y, xf, yf), b = g(X + 1, Y, xf - 1, yf), c = g(X, Y + 1, xf, yf - 1), d = g(X + 1, Y + 1, xf - 1, yf - 1);
    return (a + (b - a) * u + (c - a + (a - b - c + d) * u) * v) * 1.4;
  };
}
function newField() {
  const r = rng(seed);
  noise = makeNoise(seed * 7 + 3);
  fld = {
    f: 1.1 + r() * 1.3,           /* features across the long side */
    turns: TAU * (.42 + r() * .5), /* how far the noise can swing the heading */
    rot: r() * TAU,
    warp: .4 + r() * 1.1,
    ox: r() * 90, oy: r() * 90,
    sc: 1
  };
  fld.sc = fld.f / Math.max(1, Math.max(W, H));
  outSeed.textContent = 'No. ' + String(seed).padStart(4, '0');
}

/* ── the field ── */
let DX = 0, DY = 0;
function dir(x, y) {
  const u = x * fld.sc, v = y * fld.sc;
  const w = noise(u * .55 + 31.7, v * .55 - 7.2) * fld.warp;
  const n = noise(u + w + fld.ox, v - w + fld.oy) + .24 * noise(u * 2.3 - 11.9 + fld.ox, v * 2.3 + 5.3);
  const a = n * fld.turns + fld.rot;
  let vx = Math.cos(a), vy = Math.sin(a);
  for (let i = 0; i < vort.length; i++) {
    const o = vort[i], dx = x - o.x, dy = y - o.y, d2 = dx * dx + dy * dy;
    const d = Math.sqrt(d2) + 1e-6, g = Math.exp(-d2 / (2 * o.r * o.r)) * 3.4;
    /* tangential, tilted a little inwards so a vortex reads as a spiral, not rings */
    vx += g * ((-dy * o.s) * .95 - dx * .3) / d;
    vy += g * ((dx * o.s) * .95 - dy * .3) / d;
  }
  const m = Math.hypot(vx, vy);
  if (m < 1e-3) return false;
  DX = vx / m; DY = vy / m;
  return true;
}
let NX = 0, NY = 0;
function advance(x, y, h) {
  if (!dir(x, y)) return false;
  const ax = DX, ay = DY;
  if (!dir(x + ax * h * .5, y + ay * h * .5)) return false;
  NX = x + DX * h; NY = y + DY * h;
  return true;
}

/* ── spatial grid of every accepted sample ── */
let PX = [], PY = [], PL = [], PS = [], grid = [], cols = 0, rows = 0;
function resetGrid() {
  cols = Math.ceil(W / dsep) + 1; rows = Math.ceil(H / dsep) + 1;
  grid = Array.from({ length: cols * rows }, () => []);
  PX = []; PY = []; PL = []; PS = [];
}
function ins(x, y, id, s) {
  grid[((y / dsep) | 0) * cols + ((x / dsep) | 0)].push(PX.length);
  PX.push(x); PY.push(y); PL.push(id); PS.push(s);
}
/* points of one trace are the newest in every bucket they touched, so undo is a pop */
function unins(n) {
  for (let q = 0; q < n; q++) {
    const k = PX.length - 1;
    grid[((PY[k] / dsep) | 0) * cols + ((PX[k] / dsep) | 0)].pop();
    PX.pop(); PY.pop(); PL.pop(); PS.pop();
  }
}
/* distance to the nearest sample of any other line, or of this line further than
   2.6 separations away along it (so a spiral can close on itself), capped at d_sep */
function clearance(x, y, id, s) {
  const ci = (x / dsep) | 0, cj = (y / dsep) | 0, gap = dsep * 2.6;
  let best = dsep * dsep;
  for (let j = Math.max(0, cj - 1); j <= Math.min(rows - 1, cj + 1); j++) {
    for (let i = Math.max(0, ci - 1); i <= Math.min(cols - 1, ci + 1); i++) {
      const b = grid[j * cols + i];
      for (let q = 0; q < b.length; q++) {
        const p = b[q];
        if (PL[p] === id && Math.abs(PS[p] - s) < gap) continue;
        const dx = PX[p] - x, dy = PY[p] - y, d = dx * dx + dy * dy;
        if (d < best) best = d;
      }
    }
  }
  return Math.sqrt(best);
}
const inside = (x, y) => x >= MARGIN && y >= MARGIN && x <= W - MARGIN && y <= H - MARGIN;

function trace(sx, sy, id) {
  const fw = [], bw = [];
  ins(sx, sy, id, 0);
  let n = 1;
  for (let side = 0; side < 2; side++) {
    const h = side ? -STEP : STEP, arr = side ? bw : fw;
    let x = sx, y = sy, s = 0;
    for (let k = 0; k < MAXSTEP; k++) {
      if (!advance(x, y, h)) break;
      s += h;
      if (!inside(NX, NY)) break;
      const d = clearance(NX, NY, id, s);
      if (d < dtest) break;
      x = NX; y = NY;
      arr.push(x, y, d);
      ins(x, y, id, s); n++;
    }
  }
  if (n * STEP < dsep * 2.2) { unins(n); return null; }
  const p = new Float32Array(n * 3);
  let o = 0;
  for (let q = bw.length - 3; q >= 0; q -= 3) { p[o++] = bw[q]; p[o++] = bw[q + 1]; p[o++] = bw[q + 2]; }
  p[o++] = sx; p[o++] = sy; p[o++] = dsep;
  for (let q = 0; q < fw.length; q += 3) { p[o++] = fw[q]; p[o++] = fw[q + 1]; p[o++] = fw[q + 2]; }
  /* clearance -> pen width, smoothed over seven samples, with the ends lifted */
  const c = new Float32Array(n), wmax = Math.min(2.2, .25 * dsep);
  for (let q = 0; q < n; q++) c[q] = Math.min(1, Math.max(0, (p[q * 3 + 2] - dtest) / (dsep - dtest)));
  let len = 0;
  for (let q = 0; q < n; q++) {
    let a = 0, m = 0;
    for (let r = -3; r <= 3; r++) { const j = q + r; if (j >= 0 && j < n) { a += c[j]; m++; } }
    const end = Math.min(1, Math.min(q, n - 1 - q) / 7);
    p[q * 3 + 2] = wmax * (.16 + .84 * a / m) * (.3 + .7 * end);
    if (q) len += Math.hypot(p[q * 3] - p[q * 3 - 3], p[q * 3 + 1] - p[q * 3 - 2]);
  }
  return { p, n, len };
}

function build() {
  resetGrid();
  lines = []; total = 0;
  const r = rng(seed ^ 0x5bd1e995);
  const queue = [];
  const tryAt = (x, y) => {
    if (lines.length > 1400 || !inside(x, y) || clearance(x, y, -1, 0) < dsep * .99) return;
    const L = trace(x, y, lines.length);
    if (L) { lines.push(L); total += L.len; queue.push(L); }
  };
  const drain = () => {
    while (queue.length) {
      const L = queue.shift(), p = L.p;
      for (let q = 1; q < L.n - 1; q += 2) {
        let tx = p[q * 3 + 3] - p[q * 3 - 3], ty = p[q * 3 + 4] - p[q * 3 - 2];
        const m = Math.hypot(tx, ty) || 1;
        tx /= m; ty /= m;
        tryAt(p[q * 3] - ty * dsep, p[q * 3 + 1] + tx * dsep);
        tryAt(p[q * 3] + ty * dsep, p[q * 3 + 1] - tx * dsep);
      }
    }
  };
  tryAt(W * (.3 + r() * .4), H * (.3 + r() * .4));
  drain();
  /* pockets the front never reached: walled off by a vortex or by the frame */
  for (let y = MARGIN + dsep * .5; y < H - MARGIN; y += dsep) {
    for (let x = MARGIN + dsep * .5; x < W - MARGIN; x += dsep) { tryAt(x, y); drain(); }
  }
}

/* ── the plotter ── */
let pl = 0, pi = 0, inkDone = 0, linesDone = 0, speed = 0, headX = -1, headY = -1, plotting = false;
function wipe() {
  ix.setTransform(1, 0, 0, 1, 0, 0);
  ix.clearRect(0, 0, ink.width, ink.height);
}
function seg(L, q) {
  const p = L.p, o = q * 3;
  ix.lineWidth = (p[o + 2] + p[o + 5]) * .5;
  ix.beginPath();
  ix.moveTo(p[o], p[o + 1]);
  ix.lineTo(p[o + 3], p[o + 4]);
  ix.stroke();
  return Math.hypot(p[o + 3] - p[o], p[o + 4] - p[o + 1]);
}
function pen() {
  ix.setTransform(DPR, 0, 0, DPR, 0, 0);
  ix.lineCap = 'round';
  ix.strokeStyle = css(pal.ink, 1);
}
function replot(dur) {
  build();
  wipe();
  pl = 0; pi = 0; inkDone = 0; linesDone = 0; headX = -1;
  if (calm || !dur) {
    pen();
    for (const L of lines) for (let q = 0; q < L.n - 1; q++) seg(L, q);
    pl = lines.length; inkDone = total; linesDone = lines.length; plotting = false;
  } else {
    speed = total / dur;
    plotting = true;
  }
  readout();
  render();
  kick();
}
function plot(dt) {
  let budget = speed * dt;
  pen();
  while (budget > 0 && pl < lines.length) {
    const L = lines[pl];
    if (pi < L.n - 1) {
      const d = seg(L, pi);
      budget -= d; inkDone += d;
      headX = L.p[pi * 3 + 3]; headY = L.p[pi * 3 + 4];
      pi++;
    }
    if (pi >= L.n - 1) { pl++; pi = 0; linesDone++; }
  }
  if (pl >= lines.length) { plotting = false; inkDone = total; headX = -1; }
}
function readout() {
  outLines.textContent = linesDone.toLocaleString('en-US');
  outInk.textContent = (inkDone * MM / 1000).toFixed(2);
}

/* ── a few motes drift along the finished field ── */
const NP = 30, TR = 11;
const mx = new Float32Array(NP * TR), my = new Float32Array(NP * TR), age = new Float32Array(NP), life = new Float32Array(NP);
const mr = rng(91);
function spawn(i) {
  const x = MARGIN + mr() * (W - MARGIN * 2), y = MARGIN + mr() * (H - MARGIN * 2);
  for (let t = 0; t < TR; t++) { mx[i * TR + t] = x; my[i * TR + t] = y; }
  age[i] = 0; life[i] = 2.2 + mr() * 2.6;
}
function drift(dt) {
  for (let i = 0; i < NP; i++) {
    age[i] += dt;
    const o = i * TR, x = mx[o], y = my[o];
    if (age[i] > life[i] || !advance(x, y, 24 * dt) || !inside(NX, NY)) { spawn(i); continue; }
    for (let t = TR - 1; t > 0; t--) { mx[o + t] = mx[o + t - 1]; my[o + t] = my[o + t - 1]; }
    mx[o] = NX; my[o] = NY;
  }
}

/* ── compositing ── */
let hover = null;
const kb = { x: 0, y: 0 };
const vR = () => Math.max(24, Math.min(64, Math.min(W, H) * .2));
function glyph(x, y, s, r, a) {
  ctx.strokeStyle = css(pal.accent, a);
  ctx.fillStyle = css(pal.accent, a);
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  const a0 = -Math.PI * .5, a1 = a0 + s * Math.PI * 1.45;
  ctx.arc(x, y, r, a0, a1, s < 0);
  ctx.stroke();
  const ex = x + Math.cos(a1) * r, ey = y + Math.sin(a1) * r, tx = -Math.sin(a1) * s, ty = Math.cos(a1) * s;
  ctx.beginPath();
  ctx.moveTo(ex + tx * 3.6, ey + ty * 3.6);
  ctx.lineTo(ex - ty * 2.6 - tx * .6, ey + tx * 2.6 - ty * .6);
  ctx.lineTo(ex + ty * 2.6 - tx * .6, ey - tx * 2.6 - ty * .6);
  ctx.closePath();
  ctx.fill();
}
function render() {
  if (!W) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, cv.width, cv.height);
  ctx.drawImage(ink, 0, 0);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  if (!plotting && !calm) {
    ctx.lineCap = 'round';
    ctx.lineWidth = 1.5;
    for (let i = 0; i < NP; i++) {
      const k = Math.min(1, age[i] / .5, (life[i] - age[i]) / .6);
      if (k <= 0) continue;
      ctx.strokeStyle = css(pal.accent, .62 * k);
      ctx.beginPath();
      ctx.moveTo(mx[i * TR], my[i * TR]);
      for (let t = 1; t < TR; t++) ctx.lineTo(mx[i * TR + t], my[i * TR + t]);
      ctx.stroke();
    }
  }
  for (const o of vort) {
    ctx.fillStyle = css(pal.plate, .85);
    ctx.beginPath(); ctx.arc(o.x, o.y, 9.5, 0, TAU); ctx.fill();
    glyph(o.x, o.y, o.s, 6, 1);
  }
  if (headX >= 0) {
    ctx.fillStyle = css(pal.accent, 1);
    ctx.beginPath(); ctx.arc(headX, headY, 2.6, 0, TAU); ctx.fill();
    ctx.strokeStyle = css(pal.accent, .35);
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(headX, headY, 6, 0, TAU); ctx.stroke();
  }
  const focusKb = stage.matches(':focus-visible');
  const at = focusKb ? kb : hover;
  if (at) {
    const r = vR();
    ctx.setLineDash([3, 4]);
    ctx.strokeStyle = css(pal.accent, .55);
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(at.x, at.y, r, 0, TAU); ctx.stroke();
    ctx.setLineDash([]);
    glyph(at.x, at.y, spin, 6, .9);
  }
}

/* ── host ── */
let raf = 0, last = 0, seen = true, dead = false, inkT = 0;
function size(w, h) {
  if (w < 2 || h < 2 || (Math.abs(w - W) < .5 && Math.abs(h - H) < .5)) return;
  const first = !W, sx = W ? w / W : 1, sy = H ? h / H : 1;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = ink.width = Math.round(W * DPR);
  cv.height = ink.height = Math.round(H * DPR);
  for (const o of vort) { o.x *= sx; o.y *= sy; }
  kb.x = first ? W * .5 : kb.x * sx; kb.y = first ? H * .5 : kb.y * sy;
  if (first) newField(); else fld.sc = fld.f / Math.max(W, H);
  for (let i = 0; i < NP; i++) { spawn(i); age[i] = mr() * life[i]; }
  replot(first ? 5.2 : 0);
}
function kick() {
  if (dead || raf || calm || !seen || document.hidden) return;
  last = 0;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) return;
  const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
  last = now;
  if (plotting) {
    plot(dt);
    inkT += dt;
    if (inkT > .05 || !plotting) { inkT = 0; readout(); }
  } else drift(dt);
  render();
  raf = requestAnimationFrame(frame);
}
let rz = 0;
const ro = new ResizeObserver(([e]) => {
  const { width, height } = e.contentRect;
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; size(width, height); });
});
ro.observe(plate);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => { calm = mq.matches; if (calm && plotting) replot(0); else render(); kick(); };
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => {
  theme();
  if (!plotting) { wipe(); pen(); for (const L of lines) for (let q = 0; q < L.n - 1; q++) seg(L, q); }
  render();
});
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  cancelAnimationFrame(rz);
  clearInterval(dog);
  clearTimeout(sepT);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}

/* ── input ── */
function sync() {
  root.dataset.v = vort.length;
  outV.textContent = vort.length;
  btnClear.disabled = !vort.length;
}
function drop(x, y) {
  if (vort.length >= MAXV) vort.shift();
  vort.push({ x, y, s: spin, r: vR() });
  live.textContent = 'Vortex ' + vort.length + ' of ' + MAXV + ', turning ' + (spin > 0 ? 'clockwise' : 'anticlockwise') + '. Replotting.';
  spin = -spin;
  sync();
  replot(2.4);
}
function undo() {
  if (!vort.length) return;
  vort.pop();
  spin = -spin;
  live.textContent = vort.length + ' vortices left. Replotting.';
  sync();
  replot(2.4);
}
function clearAll() {
  if (!vort.length) return;
  vort.length = 0;
  spin = 1;
  live.textContent = 'Vortices cleared. Replotting the open field.';
  sync();
  replot(2.4);
}
function fresh() {
  seed = 1000 + ((Math.random() * 9000) | 0);
  vort.length = 0;
  spin = 1;
  newField();
  sync();
  live.textContent = 'New field, plate number ' + seed + '.';
  replot(4.2);
}
const local = (e) => { const r = stage.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };
stage.addEventListener('pointermove', (e) => { hover = local(e); if (!raf) render(); });
stage.addEventListener('pointerleave', () => { hover = null; if (!raf) render(); });
stage.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const p = local(e);
  kb.x = p.x; kb.y = p.y;
  drop(p.x, p.y);
});
stage.addEventListener('keydown', (e) => {
  const s = e.shiftKey ? 24 : 8;
  if (e.key === 'ArrowLeft') kb.x = Math.max(MARGIN, kb.x - s);
  else if (e.key === 'ArrowRight') kb.x = Math.min(W - MARGIN, kb.x + s);
  else if (e.key === 'ArrowUp') kb.y = Math.max(MARGIN, kb.y - s);
  else if (e.key === 'ArrowDown') kb.y = Math.min(H - MARGIN, kb.y + s);
  else if (e.key === 'Enter' || e.key === ' ') drop(kb.x, kb.y);
  else if (e.key === 'Backspace' || e.key === 'Delete') undo();
  else if (e.key === 'Escape') { if (!vort.length) return; clearAll(); }
  else if (e.key === 'n' || e.key === 'N') fresh();
  else return;
  e.preventDefault();
  if (!raf) render();
});
stage.addEventListener('focus', () => { if (!raf) render(); });
stage.addEventListener('blur', () => { if (!raf) render(); });
btnClear.addEventListener('click', clearAll);
btnNew.addEventListener('click', fresh);
let sepT = 0;
sepIn.addEventListener('input', () => {
  dsep = +sepIn.value; dtest = dsep * .5;
  outSep.textContent = (dsep * MM).toFixed(1) + ' mm';
  clearTimeout(sepT);
  sepT = setTimeout(() => { if (!root.isConnected) return; replot(2.4); }, 140);
});

theme();
sync();
{
  const r = plate.getBoundingClientRect();
  size(r.width, r.height);
}
kick();

css:
.fxg-arbor {
  /* Re-theme with these four; ground, summer and late-autumn tints are derived. */
  --fxg-arbor-sky: oklch(0.255 0.03 58);
  --fxg-arbor-bark: oklch(0.89 0.035 78);
  --fxg-arbor-leaf: oklch(0.8 0.17 130);
  --fxg-arbor-fall: oklch(0.72 0.165 55);

  --fxg-arbor-summer: color-mix(in oklch, var(--fxg-arbor-leaf) 62%, oklch(0.42 0.1 158));
  --fxg-arbor-late: color-mix(in oklch, var(--fxg-arbor-fall) 55%, oklch(0.46 0.13 30));
  --fxg-arbor-ground: color-mix(in oklch, var(--fxg-arbor-sky) 70%, black);
  --fxg-arbor-glow: color-mix(in oklch, var(--fxg-arbor-fall) 30%, var(--fxg-arbor-sky));
  --fxg-arbor-muted: color-mix(in oklch, var(--fxg-arbor-bark) 58%, var(--fxg-arbor-sky));
  --fxg-arbor-line: color-mix(in oklch, var(--fxg-arbor-bark) 16%, transparent);
  --fxg-arbor-chip: color-mix(in oklch, var(--fxg-arbor-sky) 72%, transparent);
  --fxg-arbor-out: cubic-bezier(.16, 1, .3, 1);
  --fxg-arbor-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" ". ." "panel panel";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 10 / 9;
  min-block-size: 310px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxg-arbor-bark);
  font-family: system-ui, sans-serif;
  background:
    radial-gradient(120% 70% at 50% 100%, var(--fxg-arbor-glow), transparent 70%),
    linear-gradient(to bottom, color-mix(in oklch, var(--fxg-arbor-sky) 80%, black), var(--fxg-arbor-sky));
  box-shadow: inset 0 0 0 1px var(--fxg-arbor-line);

  & .fxg-arbor__cv,
  & .fxg-arbor__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxg-arbor__cv { display: block; }
  & .fxg-arbor__stage {
    z-index: 1;
    outline: none;
    touch-action: pan-y;
    border-radius: inherit;
    cursor: ew-resize;
  }
  & .fxg-arbor__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxg-arbor-fall), inset 0 0 0 5px color-mix(in oklch, var(--fxg-arbor-fall) 22%, transparent);
  }

  & .fxg-arbor__head,
  & .fxg-arbor__read {
    position: relative;
    z-index: 2;
    margin: 0;
    pointer-events: none;
    text-shadow: 0 0 6px var(--fxg-arbor-sky), 0 0 14px var(--fxg-arbor-sky);
  }
  & .fxg-arbor__head { grid-area: head; min-inline-size: 0; }
  & .fxg-arbor__eyebrow {
    display: flex;
    gap: 6px;
    margin: 0 0 4px;
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-arbor-muted);
  }
  & .fxg-arbor__eyebrow span {
    font: 500 9.5px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: 0;
    text-transform: none;
    color: var(--fxg-arbor-fall);
  }
  & .fxg-arbor__title {
    display: flex;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 2px 8px;
    margin: 0;
    font: italic 500 clamp(21px, 7cqi, 30px)/1 ui-serif, Georgia, serif;
    letter-spacing: -0.01em;
    text-wrap: balance;
  }
  & .fxg-arbor__title small {
    font: 500 10px/1 ui-monospace, Menlo, monospace;
    font-style: normal;
    font-variant-numeric: tabular-nums;
    color: var(--fxg-arbor-muted);
  }
  & .fxg-arbor__rule {
    margin: 6px 0 0;
    max-inline-size: 30ch;
    font: 500 10px/1.45 ui-monospace, Menlo, monospace;
    color: var(--fxg-arbor-muted);
    text-wrap: pretty;
  }
  & .fxg-arbor__read {
    grid-area: read;
    display: grid;
    gap: 7px;
    align-self: start;
    text-align: end;
  }
  & .fxg-arbor__read div {
    display: grid;
    gap: 2px;
    transition: opacity .6s var(--fxg-arbor-out) calc(var(--i) * 80ms + 150ms), translate .8s var(--fxg-arbor-out) calc(var(--i) * 80ms + 150ms);
    @starting-style { opacity: 0; translate: 6px 0; }
  }
  & .fxg-arbor__read dt {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-arbor-muted);
  }
  & .fxg-arbor__read dd {
    margin: 0;
    font: 600 clamp(13px, 4cqi, 16px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }

  & .fxg-arbor__panel {
    grid-area: panel;
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "species grow" "season season";
    align-items: center;
    gap: 8px 8px;
    padding: 8px;
    border-radius: 12px;
    background: var(--fxg-arbor-chip);
    box-shadow: inset 0 0 0 1px var(--fxg-arbor-line);
    backdrop-filter: blur(8px);
  }
  & .fxg-arbor__species {
    grid-area: species;
    display: flex;
    gap: 2px;
    min-inline-size: 0;
    margin: 0;
    padding: 2px;
    border: 0;
    border-radius: 999px;
    background: color-mix(in oklch, var(--fxg-arbor-sky) 80%, black);
  }
  & .fxg-arbor__species label {
    position: relative;
    flex: 1;
    display: grid;
    place-items: center;
    min-inline-size: 0;
    cursor: pointer;
  }
  & .fxg-arbor__species input {
    position: absolute;
    inset: 0;
    margin: 0;
    opacity: 0;
    cursor: pointer;
  }
  & .fxg-arbor__species span {
    inline-size: 100%;
    padding: 6px 4px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    text-align: center;
    color: var(--fxg-arbor-muted);
    transition: background-color .3s var(--fxg-arbor-out), color .3s var(--fxg-arbor-out), scale .45s var(--fxg-arbor-spring);
  }
  & .fxg-arbor__species label:hover span { color: var(--fxg-arbor-bark); }
  & .fxg-arbor__species label:has(:checked) span {
    background: var(--fxg-arbor-bark);
    color: var(--fxg-arbor-sky);
  }
  & .fxg-arbor__species label:has(:active) span { scale: .94; }
  & .fxg-arbor__species label:has(:focus-visible) span { outline: 2px solid var(--fxg-arbor-fall); outline-offset: 1px; }
  & .fxg-arbor__grow {
    grid-area: grow;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    block-size: 30px;
    padding: 0 12px 0 9px;
    border: 0;
    border-radius: 999px;
    background: var(--fxg-arbor-fall);
    color: oklch(0.2 0.03 50);
    font: 650 11.5px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: background-color .25s var(--fxg-arbor-out), scale .45s var(--fxg-arbor-spring);
  }
  & .fxg-arbor__grow:hover { background: color-mix(in oklch, var(--fxg-arbor-fall) 80%, white); }
  & .fxg-arbor__grow:active { scale: .94; }
  & .fxg-arbor__grow:focus-visible { outline: 2px solid var(--fxg-arbor-bark); outline-offset: 2px; }
  & .fxg-arbor__grow svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: translate .5s var(--fxg-arbor-spring);
  }
  & .fxg-arbor__grow:hover svg { translate: 0 -1.5px; }
  & .fxg-arbor__season {
    grid-area: season;
    display: grid;
    grid-template-columns: auto minmax(40px, 1fr) 7.5ch;
    align-items: center;
    gap: 10px;
    padding-inline: 4px;
  }
  & .fxg-arbor__name {
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-arbor-muted);
  }
  & .fxg-arbor__season input {
    inline-size: 100%;
    margin: 0;
    accent-color: var(--fxg-arbor-fall);
    cursor: pointer;
  }
  & .fxg-arbor__season input:focus-visible { outline: 2px solid var(--fxg-arbor-fall); outline-offset: 3px; border-radius: 4px; }
  & .fxg-arbor__season output {
    font: 600 11px/1 ui-monospace, Menlo, monospace;
    text-align: end;
  }
  & .fxg-arbor__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: 0;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @container (max-width: 330px) {
    & .fxg-arbor__grow span { display: none; }
    & .fxg-arbor__grow { padding: 0 9px; }
    & .fxg-arbor__rule { font-size: 9px; max-inline-size: 24ch; }
    & .fxg-arbor__species span { font-size: 10.5px; }
  }
  @container (min-width: 520px) {
    & .fxg-arbor__panel { grid-template-columns: auto auto minmax(0, 1fr); grid-template-areas: "species grow season"; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxg-arbor {
    & .fxg-arbor__read div,
    & .fxg-arbor__species span,
    & .fxg-arbor__grow,
    & .fxg-arbor__grow svg { transition: none; }
  }
}

js:
/* Arbor — a bracketed, stochastic L-system (Prusinkiewicz & Lindenmayer, "The
   Algorithmic Beauty of Plants", figs 1.24 and 1.27). The axiom is rewritten n
   times; a turtle then reads the string into a hierarchy where every F is a segment
   holding only its angle relative to its parent, so one pass per frame can re-pose
   the whole tree: wind bends each segment by an amount that falls with its width,
   and willow twigs also feel a downward tropism. Widths follow the pipe model
   (cross-section ~ number of tips carried). Growth is driven along path length, so
   a branch starts only when the segment under it has finished. */
const cv = root.querySelector('.fxg-arbor__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxg-arbor__stage');
const probe = root.querySelector('.fxg-arbor__probe');
const panel = root.querySelector('.fxg-arbor__panel');
const head = root.querySelector('.fxg-arbor__head');
const live = root.querySelector('p.fxg-arbor__sr');
const seasonIn = root.querySelector('.fxg-arbor__season input');
const radios = [...root.querySelectorAll('.fxg-arbor__species input')];
const $ = (n) => root.querySelector('[data-k="' + n + '"]');
const out = { meta: $('meta'), name: $('name'), seed: $('seed'), rule: $('rule'), segs: $('segs'), leaves: $('leaves'), season: $('season') };
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2, DOWN = Math.PI / 2;
const SPECIES = [
  { name: 'Bracken', ax: 'X', rules: { X: 'F+[[X]-X]-F[-FX]+X', F: 'FF' }, d: 22.5, n: 5, trop: 0,
    rule: 'X → F+[[X]−X]−F[−FX]+X · F → FF' },
  { name: 'Hazel', ax: 'F', rules: { F: [[.33, 'F[+F]F[-F]F'], [.33, 'F[+F]F'], [.34, 'F[-F]F']] }, d: 25.7, n: 6, trop: 0,
    rule: 'F → F[+F]F[−F]F | F[+F]F | F[−F]F' },
  { name: 'Willow', ax: 'X', rules: { X: [[.5, 'F[+X][-X]FX'], [.5, 'F[-X]F[+X]X']], F: 'FF' }, d: 30, n: 6, trop: .55,
    rule: 'X → F[+X][−X]FX | F[−X]F[+X]X · F → FF' }
];

let W = 0, H = 0, DPR = 1;
let sp = 0, seed = 318, season = .9;
let N = 0, par, loc, len, dist, wid, A, X1, Y1, maxDist = 1;
let S = 1, ox = 0, oy = 0, ground = 0, speed = 1, T = 0, grown = false;
let leaves = [];
let gust = 0, clock = 0;
const pal = {};

/* ── colour ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a + ')';
const mix = (a, b, k) => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
function theme() {
  pal.bark = rgb('--fxg-arbor-bark');
  pal.leaf = rgb('--fxg-arbor-leaf');
  pal.summer = rgb('--fxg-arbor-summer');
  pal.fall = rgb('--fxg-arbor-fall');
  pal.late = rgb('--fxg-arbor-late');
  pal.ground = rgb('--fxg-arbor-ground');
  pal.sky = rgb('--fxg-arbor-sky');
}
/* spring 0 -> summer 1 -> autumn 2 -> late 2.6 -> bare 3 */
function seasonRGB(s) {
  if (s <= 0) return pal.leaf;
  if (s < 1) return mix(pal.leaf, pal.summer, s);
  if (s < 1.5) return pal.summer;
  if (s < 2.1) return mix(pal.summer, pal.fall, (s - 1.5) / .6);
  if (s < 2.7) return mix(pal.fall, pal.late, (s - 2.1) / .6);
  return pal.late;
}
const seasonName = (s) => s < .55 ? 'Spring' : s < 1.6 ? 'Summer' : s < 2.45 ? 'Autumn' : 'Winter';

function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}

/* ── rewrite, then read with a turtle ── */
function rewrite(spec, r) {
  let s = spec.ax;
  for (let g = 0; g < spec.n; g++) {
    let o = '';
    for (let i = 0; i < s.length; i++) {
      const ch = s[i], rule = spec.rules[ch];
      if (rule === undefined) { o += ch; continue; }
      if (typeof rule === 'string') { o += rule; continue; }
      let x = r(), k = 0;
      while (k < rule.length - 1 && x > rule[k][0]) { x -= rule[k][0]; k++; }
      o += rule[k][1];
