}
function build() {
  const spec = SPECIES[sp], r = rng(seed * 31 + sp);
  const s = rewrite(spec, r);
  let nF = 0;
  for (let i = 0; i < s.length; i++) if (s[i] === 'F') nF++;
  par = new Int32Array(nF); loc = new Float32Array(nF); len = new Float32Array(nF); dist = new Float32Array(nF);
  wid = new Float32Array(nF); A = new Float32Array(nF); X1 = new Float32Array(nF); Y1 = new Float32Array(nF);
  const d = spec.d * Math.PI / 180, stack = [], sites = [];
  let cur = -1, turn = 0, dd = 0;
  N = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === 'F') {
      const k = N++;
      par[k] = cur;
      loc[k] = turn + (r() - .5) * d * .3;
      len[k] = .75 + r() * .5;
      dd += len[k];
      dist[k] = dd;
      turn = 0; cur = k;
    } else if (ch === '+') turn += d * (.8 + r() * .4);
    else if (ch === '-') turn -= d * (.8 + r() * .4);
    else if (ch === '[') stack.push(cur, turn, dd);
    else if (ch === ']') { dd = stack.pop(); turn = stack.pop(); cur = stack.pop(); }
    else if (ch === 'X' && cur >= 0) sites.push(cur);
  }
  /* pipe model: a segment carries every tip above it */
  const tips = new Float32Array(N), kids = new Uint16Array(N);
  for (let k = 1; k < N; k++) if (par[k] >= 0) kids[par[k]]++;
  for (let k = 0; k < N; k++) if (!kids[k]) { tips[k] = 1; sites.push(k); }
  for (let k = N - 1; k > 0; k--) if (par[k] >= 0) tips[par[k]] += tips[k];
  maxDist = 0;
  let tmax = 1;
  for (let k = 0; k < N; k++) { maxDist = Math.max(maxDist, dist[k]); tmax = Math.max(tmax, tips[k]); }
  for (let k = 0; k < N; k++) wid[k] = Math.pow(tips[k] / tmax, .5);
