  const uniq = [...new Set(sites)];
  const per = spec.ax === 'F' ? 2 : 1, keep = Math.min(1, 860 / per / uniq.length);
  leaves = [];
  for (const k of uniq) {
    if (r() > keep) continue;
    for (let j = 0; j < per; j++) {
      leaves.push({
        k, side: (r() < .5 ? -1 : 1) * (.45 + r() * .6), size: .7 + r() * .55, u: r(),
        fallAt: 2.12 + r() * .8, st: 0, born: -1, x: 0, y: 0, vx: 0, vy: 0, rot: 0, vr: 0, ph: r() * TAU
      });
    }
  }
  out.name.textContent = spec.name;
  out.seed.textContent = 'No. ' + String(seed).padStart(4, '0');
  out.meta.textContent = 'δ ' + spec.d + '° · n ' + spec.n;
  out.rule.textContent = spec.rule;
  out.segs.textContent = N.toLocaleString('en-US');
}

/* ── posing ── */
function pose(t, w, full) {
  const trop = SPECIES[sp].trop, tt = full ? 1e9 : T, wob = calm ? 0 : 1;
  for (let k = 0; k < N; k++) {
    const p = par[k];
    let a = p < 0 ? -DOWN : A[p];
    const x = p < 0 ? ox : X1[p], y = p < 0 ? oy : Y1[p];
    const ww = wid[k] * wTrunk;
    const flex = 1 / (ww * ww * .55 + .45);
    a += loc[k] + flex * (w * .05 + Math.sin(t * 1.9 + dist[k] * .4) * .012 * wob);
    if (trop) a += trop * Math.sin(DOWN - a) / (ww * ww + .6);
    A[k] = a;
    const g = Math.min(1, Math.max(0, (tt - (dist[k] - len[k])) / len[k]));
    const L = len[k] * S * g;
    X1[k] = x + Math.cos(a) * L;
    Y1[k] = y + Math.sin(a) * L;
  }
}
let wTrunk = 6, leafLen = 5;
function fit() {
  /* the crown may rise behind the heading: its type carries a halo of sky */
  const top = head.offsetTop + Math.min(head.offsetHeight, 40);
  ground = panel.offsetTop - 12;
  wTrunk = Math.max(2.5, Math.min(8, H * .024));
  S = 1; ox = 0; oy = 0;
  pose(0, 0, true);
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = 0;
  for (let k = 0; k < N; k++) {
    x0 = Math.min(x0, X1[k]); x1 = Math.max(x1, X1[k]);
    y0 = Math.min(y0, Y1[k]); y1 = Math.max(y1, Y1[k]);
  }
  x0 = Math.min(x0, 0); x1 = Math.max(x1, 0);
  S = Math.min((W - 36) / (x1 - x0 || 1), (ground - top) / (y1 - y0 || 1));
  ox = W / 2 - (x0 + x1) / 2 * S;
  oy = ground - y1 * S;
  leafLen = Math.max(4, Math.min(9, S * 2.3 + 2.6));
}

/* ── leaves ── */
const BK = 7;
let bucket = [];
function tint() {
  bucket = Array.from({ length: BK }, (_, b) => css(seasonRGB(season + ((b + .5) / BK - .5) * .7), 1));
}
function leafPath(path, x, y, a, l) {
  const c = Math.cos(a), s = Math.sin(a), mx = x + c * l * .55, my = y + s * l * .55, nx = -s * l * .34, ny = c * l * .34;
  path.moveTo(x, y);
  path.quadraticCurveTo(mx + nx, my + ny, x + c * l, y + s * l);
  path.quadraticCurveTo(mx - nx, my - ny, x, y);
}
const backOut = (x) => { const c = 1.9; x -= 1; return 1 + (c + 1) * x * x * x + c * x * x; };
let onTree = 0;
function leafStep(dt, w) {
  onTree = 0;
  for (const L of leaves) {
    const ready = T >= dist[L.k];
    if (L.st === 0) {
      if (!ready) continue;
      if (L.born < 0) L.born = clock;
      if (season > L.fallAt) {
        const age = calm ? 1 : Math.min(1, (clock - L.born) / .55);
        L.st = 1;
        L.x = X1[L.k]; L.y = Y1[L.k]; L.rot = A[L.k] + L.side;
        L.vx = w * 18; L.vy = -6; L.vr = (L.u - .5) * 5;
        L.scale = backOut(age);
        if (calm) { L.st = 2; L.x += (L.u - .5) * 46; L.y = ground - 1 - L.u * 2; L.rot = L.u < .5 ? -.12 : Math.PI + .12; }
      } else onTree++;
    } else if (season < L.fallAt - .06) {
      L.st = 0; L.born = clock;
      onTree++;
    } else if (L.st === 1) {
      L.vy = Math.min(34, L.vy + 70 * dt);
      L.vx += ((Math.sin(clock * 2.4 + L.ph) * 34 + w * 26) - L.vx) * Math.min(1, dt * 2.2);
      L.x += L.vx * dt; L.y += L.vy * dt;
      L.rot += (L.vr + Math.sin(clock * 3.1 + L.ph) * 2.2) * dt;
      if (L.y >= ground - 1 - L.u * 2.5) {
        L.st = 2; L.y = ground - 1 - L.u * 2.5;
        L.rot = Math.cos(L.rot) > 0 ? -.12 + L.u * .2 : Math.PI + .12 - L.u * .2;
