    }
  }
}

/* ── drawing ── */
const WB = 9;
function render() {
  if (!W) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, cv.width, cv.height);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  /* ground */
  const g = ctx.createLinearGradient(0, ground - 2, 0, H);
  g.addColorStop(0, css(pal.ground, .0));
  g.addColorStop(.08, css(pal.ground, .75));
  g.addColorStop(1, css(pal.ground, .95));
  ctx.fillStyle = g;
  ctx.fillRect(0, ground - 2, W, H - ground + 2);
  ctx.strokeStyle = css(pal.bark, .16);
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(0, ground + .5); ctx.lineTo(W, ground + .5); ctx.stroke();
  const sh = ctx.createRadialGradient(ox, ground, 0, ox, ground, Math.max(30, W * .22));
  sh.addColorStop(0, css(pal.ground, .9)); sh.addColorStop(1, css(pal.ground, 0));
  ctx.fillStyle = sh;
  ctx.beginPath(); ctx.ellipse(ox, ground + 1, Math.max(30, W * .22), 6, 0, 0, TAU); ctx.fill();
