  const fallen = Array.from({ length: BK }, () => new Path2D());
  const hanging = Array.from({ length: BK }, () => new Path2D());
  for (const L of leaves) {
    const b = Math.min(BK - 1, (L.u * BK) | 0), l = leafLen * L.size;
    if (L.st === 2) leafPath(fallen[b], L.x, L.y, L.rot, l * .9);
    else if (L.st === 1) leafPath(hanging[b], L.x, L.y, L.rot, l * (L.scale || 1));
  }
  ctx.globalAlpha = .8;
  for (let b = 0; b < BK; b++) { ctx.fillStyle = bucketLate[b]; ctx.fill(fallen[b]); }
  ctx.globalAlpha = 1;
  /* branches, batched by width */
  const paths = Array.from({ length: WB }, () => new Path2D());
  const bw = new Float32Array(WB);
  for (let k = 0; k < N; k++) {
    const p = par[k];
    const x0 = p < 0 ? ox : X1[p], y0 = p < 0 ? oy : Y1[p];
    if (x0 === X1[k] && y0 === Y1[k]) continue;
    const ww = Math.max(.55, wid[k] * wTrunk);
    const b = Math.min(WB - 1, Math.round(Math.sqrt(wid[k]) * (WB - 1)));
    bw[b] = Math.max(bw[b], ww);
    paths[b].moveTo(x0, y0);
    paths[b].lineTo(X1[k], Y1[k]);
  }
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = css(pal.bark, 1);
  for (let b = 0; b < WB; b++) {
    if (!bw[b]) continue;
    ctx.lineWidth = bw[b];
    ctx.stroke(paths[b]);
  }
  /* leaves on the tree */
  const on = Array.from({ length: BK }, () => new Path2D());
  for (const L of leaves) {
    if (L.st !== 0 || L.born < 0) continue;
    const age = calm ? 1 : Math.min(1, (clock - L.born) / .55);
    const b = Math.min(BK - 1, (L.u * BK) | 0);
    leafPath(on[b], X1[L.k], Y1[L.k], A[L.k] + L.side, leafLen * L.size * backOut(age));
  }
  for (let b = 0; b < BK; b++) { ctx.fillStyle = bucket[b]; ctx.fill(on[b]); ctx.fill(hanging[b]); }
}
let bucketLate = [];
function tintLate() {
  bucketLate = Array.from({ length: BK }, (_, b) => css(mix(pal.late, pal.ground, .15 + b * .05), 1));
}

/* ── host ── */
let raf = 0, last = 0, seen = true, dead = false, readT = 0, shown = -1;
function readLeaves() {
  if (onTree !== shown) { shown = onTree; out.leaves.textContent = onTree.toLocaleString('en-US'); }
}
function regrow() {
  build();
  fit();
  speed = maxDist / 5.2;
  T = calm ? 1e9 : 0;
  clock = 0;
  if (calm) { pose(0, 0, false); leafStep(0, 0); }
  readLeaves();
  render();
  kick();
}
function size(w, h) {
  if (w < 2 || h < 2 || (Math.abs(w - W) < .5 && Math.abs(h - H) < .5)) return;
  const first = !W;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR);
  cv.height = Math.round(H * DPR);
  if (first) { regrow(); return; }
  const was = ground;
  fit();
  for (const L of leaves) if (L.st === 2) L.y += ground - was;
  pose(clock, 0, false);
  render();
}
function kick() {
  if (dead || raf || !seen || document.hidden) return;
  if (calm) { pose(0, 0, false); leafStep(0, 0); readLeaves(); render(); return; }
  last = 0;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) return;
  const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
  last = now;
  clock += dt;
  T += speed * dt;
  gust *= Math.exp(-dt * 1.4);
  const w = .28 * Math.sin(clock * .55) + .14 * Math.sin(clock * 1.37 + 2) + gust;
  pose(clock, w, false);
  leafStep(dt, w);
  render();
