/* ── input ── */
function setSeason(v, say) {
  season = Math.max(0, Math.min(3, v));
  seasonIn.value = season;
  const name = seasonName(season);
  out.season.textContent = name;
  seasonIn.setAttribute('aria-valuetext', name);
  tint();
  if (say) live.textContent = name + '.';
  kick();
}
function pick(i, say) {
  sp = i;
  radios[i].checked = true;
  if (say) live.textContent = SPECIES[i].name + ', grown from its grammar.';
  regrow();
}
let px = null, pt = 0;
stage.addEventListener('pointermove', (e) => {
  const now = performance.now();
  if (px !== null) {
    const v = (e.clientX - px) / (Math.max(8, now - pt) / 1000);
    gust += (Math.max(-1.8, Math.min(1.8, v * .0042)) - gust) * .3;
  }
  px = e.clientX; pt = now;
});
stage.addEventListener('pointerleave', () => { px = null; });
stage.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft') gust = Math.max(-1.8, gust - .7);
