  else if (e.key === 'ArrowDown') setSeason(season - .25, true);
  else if (e.key === 'Enter' || e.key === ' ') { seed = 1 + ((Math.random() * 9998) | 0); live.textContent = 'New ' + SPECIES[sp].name.toLowerCase() + ', number ' + seed + '.'; regrow(); }
  else if (e.key === '1' || e.key === '2' || e.key === '3') pick(+e.key - 1, true);
  else return;
  e.preventDefault();
});
radios.forEach((r, i) => r.addEventListener('change', () => { if (r.checked) pick(i, false); }));
root.querySelector('.fxg-arbor__grow').addEventListener('click', () => {
  seed = 1 + ((Math.random() * 9998) | 0);
  live.textContent = 'New ' + SPECIES[sp].name.toLowerCase() + ', number ' + seed + '.';
  regrow();
});
seasonIn.addEventListener('input', () => setSeason(+seasonIn.value, false));

theme();
tint();
tintLate();
setSeason(season, false);
{
  const r = cv.getBoundingClientRect();
  size(r.width, r.height);
}
kick();

css:
.fxg-morph {
  /* Re-theme with these three: the dish, the grown tissue, and the reaction front. */
  --fxg-morph-ground: oklch(0.2 0.035 18);
  --fxg-morph-tissue: oklch(0.93 0.035 82);
  --fxg-morph-edge: oklch(0.66 0.19 27);

  --fxg-morph-ink: var(--fxg-morph-tissue);
  --fxg-morph-muted: color-mix(in oklch, var(--fxg-morph-tissue) 60%, var(--fxg-morph-ground));
  --fxg-morph-line: color-mix(in oklch, var(--fxg-morph-tissue) 15%, transparent);
  --fxg-morph-chip: color-mix(in oklch, var(--fxg-morph-ground) 78%, transparent);
  --fxg-morph-well: color-mix(in oklch, var(--fxg-morph-ground) 70%, black);
  --fxg-morph-out: cubic-bezier(.16, 1, .3, 1);
  --fxg-morph-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" ". ." "panel panel";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 10 / 9;
  min-block-size: 310px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxg-morph-ground);
  color: var(--fxg-morph-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxg-morph-line);

  & .fxg-morph__cv,
  & .fxg-morph__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxg-morph__cv { display: block; }
  & .fxg-morph__stage {
    z-index: 1;
    outline: none;
    touch-action: pan-y;
    border-radius: inherit;
    cursor: crosshair;
  }
  & .fxg-morph__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxg-morph-edge), inset 0 0 0 5px color-mix(in oklch, var(--fxg-morph-edge) 22%, transparent);
  }

  & .fxg-morph__head,
  & .fxg-morph__read {
    position: relative;
    z-index: 2;
    margin: 0;
    pointer-events: none;
  }
  & .fxg-morph__head {
    grid-area: head;
