/* Morphogen — Gray-Scott reaction-diffusion, u + 2v -> 3v, v -> P:
     du/dt = Du lap(u) - u v^2 + F (1 - u)
     dv/dt = Dv lap(v) + u v^2 - (F + k) v
   with Du = 1, Dv = 0.5, dt = 1 and Karl Sims' 3x3 Laplacian (0.2 edges, 0.05
   corners) on a wrapping grid of ~22k cells, stepped twelve times a frame. The pad
   plots feed F against kill k with Pearson's named regimes and the saddle-node line
   k = sqrt(F)/2 - F, beyond which no uniform reacting state exists. The image is
   shaded as relief: the gradient of v is a surface normal lit from the pointer. */
const cv = root.querySelector('.fxg-morph__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxg-morph__stage');
const probe = root.querySelector('.fxg-morph__probe');
const pad = root.querySelector('.fxg-morph__pad');
const live = root.querySelector('p.fxg-morph__sr');
const radios = [...root.querySelectorAll('.fxg-morph__presets input')];
const $ = (n) => root.querySelector('[data-k="' + n + '"]');
const outF = $('F'), outK = $('k'), outCov = $('cov'), outSteps = $('steps'), outSeed = $('seed');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const PRESETS = [
  { name: 'Coral', F: .0545, k: .062 },
  { name: 'Mitosis', F: .0367, k: .0649 },
  { name: 'Maze', F: .029, k: .057 },
  { name: 'Worms', F: .078, k: .061 }
];
const K0 = .045, K1 = .07, F0 = 0, F1 = .1, PER = 11;
let F = PRESETS[0].F, K = PRESETS[0].k;
let W = 0, H = 0, DPR = 1, cell = 2.5, gw = 0, gh = 0;
let U, V, U2, V2, img = null;
const off = document.createElement('canvas'), ox = off.getContext('2d');
let seed = 4127, steps = 0;
const lut = new Uint8ClampedArray(256 * 3);
const pal = {};

/* ── colour ── */
const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
function theme() {
  pal.ground = rgb('--fxg-morph-ground');
  pal.tissue = rgb('--fxg-morph-tissue');
  pal.edge = rgb('--fxg-morph-edge');
  /* dish -> reaction front -> grown tissue, with the front held narrow */
  for (let i = 0; i < 256; i++) {
    const t = i / 255;
    let a, b, m;
    if (t < .42) { a = pal.ground; b = pal.edge; m = Math.pow(t / .42, 1.6); }
    else { a = pal.edge; b = pal.tissue; m = Math.min(1, (t - .42) / .5); m = m * m * (3 - 2 * m); }
    for (let c = 0; c < 3; c++) lut[i * 3 + c] = a[c] + (b[c] - a[c]) * m;
  }
}

function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}

/* ── the dish ── */
function alloc(w, h) {
  const n = w * h, nu = new Float32Array(n).fill(1), nv = new Float32Array(n);
  if (U) {
    /* carry the pattern across a resize by nearest-cell resampling */
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
      const sx = Math.min(gw - 1, (x * gw / w) | 0), sy = Math.min(gh - 1, (y * gh / h) | 0);
      nu[y * w + x] = U[sy * gw + sx]; nv[y * w + x] = V[sy * gw + sx];
    }
  }
  gw = w; gh = h;
  U = nu; V = nv; U2 = new Float32Array(n); V2 = new Float32Array(n);
  off.width = gw; off.height = gh;
  img = ox.createImageData(gw, gh);
}
function drop(cx, cy, r) {
  const r2 = r * r;
  for (let dy = -Math.ceil(r); dy <= Math.ceil(r); dy++) {
    for (let dx = -Math.ceil(r); dx <= Math.ceil(r); dx++) {
      if (dx * dx + dy * dy > r2) continue;
      const x = ((Math.round(cx) + dx) % gw + gw) % gw, y = ((Math.round(cy) + dy) % gh + gh) % gh;
      U[y * gw + x] = .5; V[y * gw + x] = .25 + .25 * Math.random();
    }
  }
}
function sow() {
  U.fill(1); V.fill(0);
  const r = rng(seed);
  const n = 6 + ((r() * 6) | 0);
  for (let i = 0; i < n; i++) {
    const cx = r() * gw, cy = r() * gh, s = 2.5 + r() * 5;
    if (r() < .35) {
      /* a short scratch rather than a blot gives the front a direction */
      const a = r() * Math.PI * 2, L = 6 + r() * 16;
      for (let t = 0; t <= L; t += 1.5) drop(cx + Math.cos(a) * t, cy + Math.sin(a) * t, 1.6);
    } else drop(cx, cy, s);
  }
  steps = 0;
  outSeed.textContent = String(seed).padStart(4, '0');
}
function step(n) {
  const w = gw, h = gh, f = F, kf = K + F;
  for (let it = 0; it < n; it++) {
    for (let y = 0; y < h; y++) {
      const y0 = y * w, ym = (y ? y - 1 : h - 1) * w, yp = (y < h - 1 ? y + 1 : 0) * w;
      for (let x = 0; x < w; x++) {
        const xm = x ? x - 1 : w - 1, xp = x < w - 1 ? x + 1 : 0, i = y0 + x;
        const a = U[i], b = V[i];
        const la = (U[y0 + xm] + U[y0 + xp] + U[ym + x] + U[yp + x]) * .2 + (U[ym + xm] + U[ym + xp] + U[yp + xm] + U[yp + xp]) * .05 - a;
        const lb = (V[y0 + xm] + V[y0 + xp] + V[ym + x] + V[yp + x]) * .2 + (V[ym + xm] + V[ym + xp] + V[yp + xm] + V[yp + xp]) * .05 - b;
        const abb = a * b * b;
        U2[i] = a + la - abb + f * (1 - a);
        V2[i] = b + .5 * lb + abb - kf * b;
      }
    }
    let t = U; U = U2; U2 = t;
    t = V; V = V2; V2 = t;
  }
  steps += n;
}

/* ── picture ── */
let lx = -.7, ly = -.7, lightA = -2.35, lightT = -2.35;
let brush = null;
const kb = { x: 0, y: 0 };
function paint() {
  const d = img.data, w = gw, h = gh;
  lx = Math.cos(lightA); ly = Math.sin(lightA);
  for (let y = 0; y < h; y++) {
    const y0 = y * w, ym = (y ? y - 1 : h - 1) * w, yp = (y < h - 1 ? y + 1 : 0) * w;
    for (let x = 0; x < w; x++) {
      const xm = x ? x - 1 : w - 1, xp = x < w - 1 ? x + 1 : 0, i = y0 + x;
      const gx = V[y0 + xp] - V[y0 + xm], gy = V[yp + x] - V[ym + x];
      const s = 1 - (gx * lx + gy * ly) * 2.6;
      const t = Math.min(255, Math.max(0, (V[i] * 3.2 * 255) | 0)) * 3, o = i * 4;
      d[o] = lut[t] * s; d[o + 1] = lut[t + 1] * s; d[o + 2] = lut[t + 2] * s; d[o + 3] = 255;
    }
  }
  ox.putImageData(img, 0, 0);
}
function render() {
  if (!W) return;
  paint();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(off, 0, 0, gw * cell * DPR, gh * cell * DPR);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  const at = stage.matches(':focus-visible') ? { x: kb.x * cell, y: kb.y * cell } : brush;
  if (at) {
    ctx.strokeStyle = css(pal.tissue, .85);
    ctx.lineWidth = 1.25;
    ctx.beginPath(); ctx.arc(at.x, at.y, BR * cell, 0, Math.PI * 2); ctx.stroke();
    ctx.strokeStyle = css(pal.ground, .5);
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(at.x, at.y, BR * cell + 1.6, 0, Math.PI * 2); ctx.stroke();
  }
}
let covT = 0, dead0 = 0;
function readout() {
  let c = 0, vmax = 0;
  for (let i = 0; i < V.length; i++) { if (V[i] > .2) c++; if (V[i] > vmax) vmax = V[i]; }
  /* a regime that starves the dish (high k, low F) would leave it blank for good:
     after a moment of nothing, a few spores land so it can try again */
  if (vmax < .02) {
    if (++dead0 > 4) {
      dead0 = 0;
      const r = rng(steps + seed);
      for (let i = 0; i < 4; i++) drop(r() * gw, r() * gh, 3 + r() * 3);
      live.textContent = 'The dish died out at these rates; four spores were dropped.';
    }
  } else dead0 = 0;
  outCov.textContent = Math.round(c / V.length * 100);
  outSteps.textContent = steps < 1000 ? String(steps) : (steps / 1000).toFixed(1) + 'k';
}

/* ── feed/kill pad ── */
const fmt = (v) => v.toFixed(4).replace(/^0/, '');
function padSync() {
  const x = (K - K0) / (K1 - K0), y = 1 - (F - F0) / (F1 - F0);
  pad.style.setProperty('--x', x.toFixed(4));
  pad.style.setProperty('--y', y.toFixed(4));
  outF.textContent = fmt(F); outK.textContent = fmt(K);
  pad.setAttribute('aria-valuenow', Math.round(x * 100));
  pad.setAttribute('aria-valuetext', 'F ' + F.toFixed(4) + ', k ' + K.toFixed(4));
  let hit = -1;
  PRESETS.forEach((p, i) => { if (Math.abs(p.F - F) < 1e-4 && Math.abs(p.k - K) < 1e-4) hit = i; });
  radios.forEach((r, i) => { r.checked = i === hit; });
  dots.forEach((d, i) => d.toggleAttribute('data-on', i === hit));
}
const svgNS = 'http://www.w3.org/2000/svg';
const dots = PRESETS.map((p) => {
  const c = document.createElementNS(svgNS, 'circle');
  c.setAttribute('cx', ((p.k - K0) / (K1 - K0) * 100).toFixed(2));
  c.setAttribute('cy', ((1 - (p.F - F0) / (F1 - F0)) * 100).toFixed(2));
  c.setAttribute('r', '2.6');
  root.querySelector('.fxg-morph__dots').appendChild(c);
  return c;
});
{
  let d = '';
  for (let i = 0; i <= 60; i++) {
    const f = F0 + (F1 - F0) * i / 60, k = Math.sqrt(f) / 2 - f;
    const x = (k - K0) / (K1 - K0) * 100, y = (1 - (f - F0) / (F1 - F0)) * 100;
    d += (d ? 'L' : 'M') + x.toFixed(2) + ' ' + y.toFixed(2);
  }
  root.querySelector('.fxg-morph__curve').setAttribute('d', d);
}
function setFK(f, k) {
  F = Math.max(.005, Math.min(F1, f));
  K = Math.max(K0, Math.min(K1, k));
  padSync();
  settle();
}
/* reduced motion: no live loop, so a change is run forward and shown once */
function settle() {
  if (!calm || !W) return;
  step(700);
  render(); readout();
}

/* ── host ── */
let raf = 0, last = 0, seen = true, dead = false, clock = 0;
const BR = 3.2;
function size(w, h) {
  if (w < 2 || h < 2 || (Math.abs(w - W) < .5 && Math.abs(h - H) < .5)) return;
  const first = !W;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  cell = Math.max(1.8, Math.min(3, Math.sqrt(W * H / 29000)));
  alloc(Math.ceil(W / cell), Math.ceil(H / cell));
  if (first) {
    kb.x = gw / 2; kb.y = gh / 2;
    sow();
    step(calm ? 3200 : 900);
  }
  render();
  readout();
}
function kick() {
  if (dead || raf || calm || !seen || document.hidden) return;
  last = 0;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) return;
  const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
  last = now;
  clock += dt;
  if (!brush) lightT = -2.35 + Math.sin(clock * .21) * .7;
  let da = lightT - lightA;
  da = Math.atan2(Math.sin(da), Math.cos(da));
  lightA += da * (1 - Math.exp(-dt * 3));
  step(PER);
  render();
  covT += dt;
  if (covT > .35) { covT = 0; readout(); }
  raf = requestAnimationFrame(frame);
}
let rz = 0;
const ro = new ResizeObserver(([e]) => {
  const { width, height } = e.contentRect;
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; size(width, height); });
});
ro.observe(cv);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => { calm = mq.matches; if (calm) settle(); kick(); };
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => { theme(); render(); });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  cancelAnimationFrame(rz);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}

/* ── input: the dish ── */
let painting = null;
const local = (e) => { const r = stage.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };
function aim(p) {
  brush = p;
  lightT = Math.atan2(p.y - H / 2, p.x - W / 2);
}
stage.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  const p = local(e);
  try { stage.setPointerCapture(e.pointerId); } catch (err) { /* synthetic pointer */ }
  painting = { id: e.pointerId, x: p.x, y: p.y };
  aim(p);
  drop(p.x / cell, p.y / cell, BR);
  if (calm) settle(); else render();
});
stage.addEventListener('pointermove', (e) => {
  const p = local(e);
  aim(p);
  if (painting && painting.id === e.pointerId) {
    const d = Math.hypot(p.x - painting.x, p.y - painting.y), n = Math.ceil(d / (cell * 2));
    for (let i = 1; i <= n; i++) drop((painting.x + (p.x - painting.x) * i / n) / cell, (painting.y + (p.y - painting.y) * i / n) / cell, BR * .8);
    painting.x = p.x; painting.y = p.y;
  }
  if (calm) render();
});
const endPaint = (e) => { if (painting && painting.id === e.pointerId) { painting = null; if (calm) settle(); } };
stage.addEventListener('pointerup', endPaint);
stage.addEventListener('pointercancel', endPaint);
stage.addEventListener('pointerleave', () => { if (!painting) brush = null; if (calm) render(); });
function newDish() {
  seed = 1 + ((Math.random() * 9998) | 0);
  sow();
  step(calm ? 3200 : 120);
  live.textContent = 'New dish sown, number ' + seed + '.';
  render(); readout();
}
stage.addEventListener('keydown', (e) => {
  const s = e.shiftKey ? 8 : 3;
  if (e.key === 'ArrowLeft') kb.x = (kb.x - s + gw) % gw;
  else if (e.key === 'ArrowRight') kb.x = (kb.x + s) % gw;
  else if (e.key === 'ArrowUp') kb.y = (kb.y - s + gh) % gh;
  else if (e.key === 'ArrowDown') kb.y = (kb.y + s) % gh;
  else if (e.key === 'Enter' || e.key === ' ') { drop(kb.x, kb.y, BR); live.textContent = 'Catalyst dropped.'; settle(); }
  else if (e.key === 'n' || e.key === 'N') newDish();
  else return;
  e.preventDefault();
  lightT = Math.atan2(kb.y * cell - H / 2, kb.x * cell - W / 2);
  if (calm) render();
});
stage.addEventListener('focus', () => { if (calm) render(); });
stage.addEventListener('blur', () => { if (calm) render(); });
root.querySelector('.fxg-morph__new').addEventListener('click', newDish);

/* ── input: presets and pad ── */
radios.forEach((r, i) => r.addEventListener('change', () => {
  if (!r.checked) return;
  /* a regime is grown from the same spores rather than forced onto the last one's tissue */
  sow();
  setFK(PRESETS[i].F, PRESETS[i].k);
  if (calm) { step(2500); render(); readout(); } else step(160);
  live.textContent = PRESETS[i].name + ': F ' + PRESETS[i].F + ', k ' + PRESETS[i].k + '.';
}));
let padDrag = null;
function padAt(e) {
  const r = pad.getBoundingClientRect();
  const x = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width)), y = Math.max(0, Math.min(1, (e.clientY - r.top) / r.height));
  /* snap to a named regime when the pointer lands close to one */
  for (const p of PRESETS) {
    const px = (p.k - K0) / (K1 - K0), py = 1 - (p.F - F0) / (F1 - F0);
    if (Math.hypot(px - x, py - y) < .06) { setFK(p.F, p.k); return; }
  }
  setFK(F0 + (1 - y) * (F1 - F0), K0 + x * (K1 - K0));
}
pad.addEventListener('pointerdown', (e) => {
  if (e.button !== 0) return;
  try { pad.setPointerCapture(e.pointerId); } catch (err) { /* synthetic pointer */ }
  padDrag = e.pointerId;
  pad.setAttribute('data-drag', '');
  padAt(e);
});
pad.addEventListener('pointermove', (e) => { if (padDrag === e.pointerId) padAt(e); });
const endPad = (e) => { if (padDrag === e.pointerId) { padDrag = null; pad.removeAttribute('data-drag'); } };
pad.addEventListener('pointerup', endPad);
pad.addEventListener('pointercancel', endPad);
pad.addEventListener('keydown', (e) => {
  const s = e.shiftKey ? 4 : 1;
  if (e.key === 'ArrowLeft') setFK(F, K - .0005 * s);
  else if (e.key === 'ArrowRight') setFK(F, K + .0005 * s);
  else if (e.key === 'ArrowUp') setFK(F + .001 * s, K);
  else if (e.key === 'ArrowDown') setFK(F - .001 * s, K);
  else if (e.key === 'Home') setFK(PRESETS[0].F, PRESETS[0].k);
  else return;
  e.preventDefault();
});

theme();
padSync();
{
  const r = cv.getBoundingClientRect();
  size(r.width, r.height);
}
kick();

