.fxg-stipple {
  /* Re-theme with these three; paper tints, rules and chips are derived. */
  --fxg-stipple-paper: oklch(0.972 0.011 88);
  --fxg-stipple-ink: oklch(0.235 0.028 262);
  --fxg-stipple-sun: oklch(0.74 0.15 68);

  --fxg-stipple-muted: color-mix(in oklch, var(--fxg-stipple-ink) 56%, var(--fxg-stipple-paper));
  --fxg-stipple-line: color-mix(in oklch, var(--fxg-stipple-ink) 13%, transparent);
  --fxg-stipple-chip: color-mix(in oklch, var(--fxg-stipple-paper) 86%, transparent);
  --fxg-stipple-wash: color-mix(in oklch, var(--fxg-stipple-sun) 18%, var(--fxg-stipple-paper));
  --fxg-stipple-out: cubic-bezier(.16, 1, .3, 1);
  --fxg-stipple-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" ". ." "bar bar";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 10 / 9;
  min-block-size: 300px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxg-stipple-paper);
  color: var(--fxg-stipple-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxg-stipple-line);

  & .fxg-stipple__cv,
  & .fxg-stipple__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxg-stipple__cv { display: block; }
  & .fxg-stipple__stage {
    z-index: 1;
    outline: none;
    touch-action: pan-y;
    border-radius: inherit;
    cursor: crosshair;
  }
  & .fxg-stipple__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxg-stipple-sun), inset 0 0 0 5px color-mix(in oklch, var(--fxg-stipple-sun) 22%, transparent);
  }
  & .fxg-stipple__head,
  & .fxg-stipple__read {
    position: relative;
    z-index: 2;
    margin: 0;
    pointer-events: none;
    text-shadow: 0 0 4px var(--fxg-stipple-paper), 0 0 10px var(--fxg-stipple-paper);
  }
  & .fxg-stipple__head { grid-area: head; min-inline-size: 0; }
  & .fxg-stipple__eyebrow {
    margin: 0 0 4px;
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-stipple-muted);
  }
  & .fxg-stipple__title {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 2px 8px;
    margin: 0;
    font-size: clamp(18px, 6cqi, 25px);
    font-weight: 300;
    line-height: 1.05;
    letter-spacing: -0.02em;
    text-wrap: balance;
  }
  & .fxg-stipple__title span {
    font: 500 10px/1 ui-monospace, Menlo, monospace;
    letter-spacing: 0;
    font-variant-numeric: tabular-nums;
    color: var(--fxg-stipple-muted);
  }
  & .fxg-stipple__read {
    grid-area: read;
    display: grid;
    gap: 7px;
    align-self: start;
    text-align: end;
  }
  & .fxg-stipple__read div {
    display: grid;
    gap: 2px;
    transition: opacity .6s var(--fxg-stipple-out) calc(var(--i) * 80ms + 150ms), translate .8s var(--fxg-stipple-out) calc(var(--i) * 80ms + 150ms);
    @starting-style { opacity: 0; translate: 6px 0; }
  }
  & .fxg-stipple__read dt {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-stipple-muted);
  }
  & .fxg-stipple__read dd {
    margin: 0;
    font: 600 clamp(12px, 3.8cqi, 15px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxg-stipple__read small { margin-inline-start: 2px; font-size: .72em; color: var(--fxg-stipple-muted); }
  & .fxg-stipple__dim { color: var(--fxg-stipple-muted); font-weight: 400; }

  & .fxg-stipple__bar {
    grid-area: bar;
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 6px;
    padding: 6px;
    border-radius: 12px;
    background: var(--fxg-stipple-chip);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px var(--fxg-stipple-line), 0 10px 22px -16px color-mix(in oklch, var(--fxg-stipple-ink) 50%, transparent);
  }
  & .fxg-stipple__count {
    display: flex;
    align-items: center;
    gap: 2px;
    min-inline-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
  }
  & .fxg-stipple__count legend {
    float: left;
    margin-inline: 4px 6px;
    padding: 0;
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-stipple-muted);
  }
  & .fxg-stipple__count label { position: relative; display: grid; cursor: pointer; }
  & .fxg-stipple__count input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & .fxg-stipple__count span {
    padding: 6px 8px;
    border-radius: 999px;
    font: 600 11px/1 ui-monospace, Menlo, monospace;
    color: var(--fxg-stipple-muted);
    transition: background-color .3s var(--fxg-stipple-out), color .3s var(--fxg-stipple-out), scale .45s var(--fxg-stipple-spring);
  }
  & .fxg-stipple__count label:hover span { color: var(--fxg-stipple-ink); background: var(--fxg-stipple-wash); }
  & .fxg-stipple__count label:has(:checked) span { background: var(--fxg-stipple-ink); color: var(--fxg-stipple-paper); }
  & .fxg-stipple__count label:has(:active) span { scale: .92; }
  & .fxg-stipple__count label:has(:focus-visible) span { outline: 2px solid var(--fxg-stipple-sun); outline-offset: 1px; }
  & .fxg-stipple__btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    block-size: 28px;
    padding: 0 10px 0 8px;
    border: 0;
    border-radius: 999px;
    background: transparent;
    box-shadow: inset 0 0 0 1px var(--fxg-stipple-line);
    color: var(--fxg-stipple-ink);
    font: 600 11px/1 system-ui, sans-serif;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color .25s var(--fxg-stipple-out), box-shadow .25s var(--fxg-stipple-out), scale .45s var(--fxg-stipple-spring);
  }
  & .fxg-stipple__btn:hover:not(:disabled) { background: var(--fxg-stipple-wash); }
  & .fxg-stipple__btn:disabled { opacity: .4; cursor: default; }
  & .fxg-stipple__btn:active { scale: .94; }
  & .fxg-stipple__btn:focus-visible { outline: 2px solid var(--fxg-stipple-sun); outline-offset: 2px; }
  & .fxg-stipple__btn svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.4;
    stroke-linecap: round;
  }
  & .fxg-stipple__btn--orbit[aria-pressed="true"] { background: var(--fxg-stipple-wash); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--fxg-stipple-sun) 55%, transparent); }
  & .fxg-stipple__btn--orbit[aria-pressed="true"] svg { color: color-mix(in oklch, var(--fxg-stipple-sun) 70%, var(--fxg-stipple-ink)); animation: fxg-stipple-turn 9s linear infinite; }
  & .fxg-stipple__btn--go { background: var(--fxg-stipple-ink); box-shadow: none; color: var(--fxg-stipple-paper); }
  & .fxg-stipple__btn--go:hover { background: color-mix(in oklch, var(--fxg-stipple-ink) 84%, var(--fxg-stipple-sun)); }
  & .fxg-stipple__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @container (max-width: 360px) {
    & .fxg-stipple__btn span { display: none; }
    & .fxg-stipple__btn { padding: 0 8px; }
  }
  @container (max-width: 300px) {
    & .fxg-stipple__count legend { display: none; }
  }
}

@keyframes fxg-stipple-turn { to { rotate: 1turn; } }

@media (prefers-reduced-motion: reduce) {
  .fxg-stipple {
    & .fxg-stipple__read div,
    & .fxg-stipple__count span,
    & .fxg-stipple__btn { transition: none; }
    & .fxg-stipple__btn--orbit[aria-pressed="true"] svg { animation: none; }
  }
}

js:
/* Stipple study — weighted Voronoi stippling (Secord, NPAR 2002). The target is a
   density raster: seeded ellipsoid pebbles resting on a table, ray-cast per sample
   with Lambert shading, cast shadows (ray against each ellipsoid, scaled to a unit
   sphere) and contact occlusion, then density = (1 - brightness)^1.15. Each frame
   is one Lloyd step: every raster sample is given to its nearest dot (uniform grid,
   3x3 cells, widened when empty) and each dot moves to the density-weighted
   centroid of what it received, sized by the mean density of its cell. Dots that
   received nothing are re-drawn from the density by rejection sampling. */
const cv = root.querySelector('.fxg-stipple__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxg-stipple__stage');
const probe = root.querySelector('.fxg-stipple__probe');
const live = root.querySelector('p.fxg-stipple__sr');
const radios = [...root.querySelectorAll('.fxg-stipple__count input')];
const btnOrbit = root.querySelector('.fxg-stipple__btn--orbit');
const $ = (n) => root.querySelector('[data-k="' + n + '"]');
const outAz = $('az'), outEl = $('el'), outDrift = $('drift'), outSeed = $('seed');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2, RAD = Math.PI / 180, SS = 2;   /* raster samples are 2 css px */
let W = 0, H = 0, DPR = 1, dw = 0, dh = 0;
let dens = null;
let N = 4000, PX = new Float32Array(0), PY = new Float32Array(0), PR = new Float32Array(0);
let sx, sy, sw, cnt;
let gcell = 8, gcols = 0, grows = 0, ghead = null, gnext = null;
let seed = 611, stones = [];
let az = 225 * RAD, el = 34 * RAD;
let orbit = true;
const pal = {};

/* ── colour ── */
const swc = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  swc.clearRect(0, 0, 1, 1);
  swc.fillStyle = '#000';
  swc.fillStyle = getComputedStyle(probe).color;
  swc.fillRect(0, 0, 1, 1);
  const d = swc.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
function theme() { pal.ink = rgb('--fxg-stipple-ink'); pal.sun = rgb('--fxg-stipple-sun'); pal.paper = rgb('--fxg-stipple-paper'); }
function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}
const hash = (x, y) => { let h = Math.imul(x, 374761393) + Math.imul(y, 668265263); h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967296; };

/* ── the scene: ellipsoid pebbles resting on z = 0, in raster units ── */
function scene() {
  const r = rng(seed * 13 + 5);
  stones = [];
  const m = Math.min(dw, dh), want = 3 + ((r() * 4) | 0);
  for (let t = 0; t < 400 && stones.length < want; t++) {
    const a = m * (.075 + r() * .1), b = a * (.6 + r() * .36), c = Math.min(a, b) * (.5 + r() * .3);
    const x = dw * (.16 + r() * .68), y = dh * (.3 + r() * .46), th = r() * Math.PI;
    if (stones.some((s) => Math.hypot(s.x - x, s.y - y) < (s.a + a) * 1.08)) continue;
    stones.push({ x, y, a, b, c, co: Math.cos(th), si: Math.sin(th), alb: .7 + r() * .3, grain: .05 + r() * .12 });
  }
  outSeed.textContent = 'No. ' + String(seed).padStart(4, '0');
}
let L0 = 0, L1 = 0, L2 = 1;
/* does the ray from (ox, oy, oz) towards the sun meet stone s? */
function blocked(s, ox, oy, oz) {
  const dx = ox - s.x, dy = oy - s.y;
  const u = (dx * s.co + dy * s.si) / s.a, v = (-dx * s.si + dy * s.co) / s.b, w = (oz - s.c) / s.c;
  const du = (L0 * s.co + L1 * s.si) / s.a, dv = (-L0 * s.si + L1 * s.co) / s.b, dz = L2 / s.c;
  const A = du * du + dv * dv + dz * dz, B = 2 * (u * du + v * dv + w * dz), C = u * u + v * v + w * w - 1;
  const D = B * B - 4 * A * C;
  if (D < 0) return false;
  return (-B - Math.sqrt(D)) / (2 * A) > 1e-3;
}
function shade() {
  L0 = Math.cos(az) * Math.cos(el); L1 = Math.sin(az) * Math.cos(el); L2 = Math.sin(el);
  const ns = stones.length;
  for (let y = 0; y < dh; y++) {
    for (let x = 0; x < dw; x++) {
      const px = x + .5, py = y + .5;
      let top = -1, z = 0, ao = 1, nu = 0, nv = 0, nz = 0;
      for (let k = 0; k < ns; k++) {
        const s = stones[k], dx = px - s.x, dy = py - s.y;
        const u = dx * s.co + dy * s.si, v = -dx * s.si + dy * s.co;
        const q = u * u / (s.a * s.a) + v * v / (s.b * s.b);
        if (q < 1) {
          const h = s.c + s.c * Math.sqrt(1 - q);
          if (h > z) { z = h; top = k; nu = u / (s.a * s.a); nv = v / (s.b * s.b); nz = (h - s.c) / (s.c * s.c); }
        } else {
          /* contact shadow: the table darkens where a pebble sits on it */
          const gap = (Math.sqrt(q) - 1) * Math.min(s.a, s.b);
          ao = Math.min(ao, 1 - .6 * Math.exp(-gap / (s.c * .35)));
        }
      }
      let b;
      if (top >= 0) {
        const s = stones[top];
        const nx = nu * s.co - nv * s.si, ny = nu * s.si + nv * s.co, m = Math.hypot(nx, ny, nz) || 1;
        let lam = Math.max(0, (nx * L0 + ny * L1 + nz * L2) / m);
        for (let k = 0; k < ns; k++) if (k !== top && lam > 0 && blocked(stones[k], px, py, z)) lam *= .2;
        /* the silhouette darkens towards the rim so a lit pebble still parts from the table */
        const rim = Math.pow(nz / m, .5);
        b = (.08 + 1.15 * lam / Math.max(.45, L2)) * s.alb * (.5 + .5 * rim) + (hash(x, y + top * 977) - .5) * s.grain;
      } else {
        let lit = 1;
        for (let k = 0; k < ns; k++) if (blocked(stones[k], px, py, 0)) { lit = 0; break; }
        b = (.2 + .7 * lit) * ao;
      }
      const d = 1 - Math.max(0, Math.min(1, b));
      dens[y * dw + x] = Math.pow(d, 1.15) + .012;
    }
  }
}

/* ── dots ── */
let sampler = rng(7);
function place(p) {
  for (let t = 0; t < 400; t++) {
    const x = sampler() * dw, y = sampler() * dh;
    if (sampler() < dens[(y | 0) * dw + (x | 0)]) { PX[p] = x; PY[p] = y; return; }
  }
  PX[p] = sampler() * dw; PY[p] = sampler() * dh;
}
function resize(n) {
  const ox = PX, oy = PY, keep = Math.min(n, ox.length);
  PX = new Float32Array(n); PY = new Float32Array(n); PR = new Float32Array(n).fill(.8);
  PX.set(ox.subarray(0, keep)); PY.set(oy.subarray(0, keep));
  for (let p = keep; p < n; p++) place(p);
  sx = new Float32Array(n); sy = new Float32Array(n); sw = new Float32Array(n); cnt = new Uint16Array(n);
  gnext = new Int32Array(n);
  N = n;
}
function grid() {
  gcell = Math.max(4, Math.sqrt(dw * dh / N) * 1.6);
  gcols = Math.ceil(dw / gcell) + 1; grows = Math.ceil(dh / gcell) + 1;
  if (!ghead || ghead.length !== gcols * grows) ghead = new Int32Array(gcols * grows);
  ghead.fill(-1);
  for (let p = 0; p < N; p++) {
    const c = Math.min(grows - 1, Math.max(0, (PY[p] / gcell) | 0)) * gcols + Math.min(gcols - 1, Math.max(0, (PX[p] / gcell) | 0));
    gnext[p] = ghead[c]; ghead[c] = p;
  }
}
let drift = 0;
function lloyd() {
  grid();
  sx.fill(0); sy.fill(0); sw.fill(0); cnt.fill(0);
  let last = -1;
  for (let y = 0; y < dh; y++) {
    const cy = (y / gcell) | 0, py = y + .5;
    for (let x = 0; x < dw; x++) {
      const rho = dens[y * dw + x];
      const cx = (x / gcell) | 0, px = x + .5;
      let best = Infinity, bp = -1;
      /* the previous sample's owner is usually this one's too: it seeds the bound */
      if (last >= 0) { const dx = PX[last] - px, dy = PY[last] - py; best = dx * dx + dy * dy; bp = last; }
      for (let ring = 1; ring < 6; ring++) {
        for (let j = cy - ring; j <= cy + ring; j++) {
          if (j < 0 || j >= grows) continue;
          for (let i = cx - ring; i <= cx + ring; i++) {
            if (i < 0 || i >= gcols) continue;
            if (ring > 1 && j > cy - ring && j < cy + ring && i > cx - ring && i < cx + ring) continue;
            for (let p = ghead[j * gcols + i]; p >= 0; p = gnext[p]) {
              const dx = PX[p] - px, dy = PY[p] - py, d = dx * dx + dy * dy;
              if (d < best) { best = d; bp = p; }
            }
          }
        }
        if (bp >= 0 && best <= (ring * gcell) * (ring * gcell)) break;
      }
      last = bp;
      if (bp < 0) continue;
      sx[bp] += rho * px; sy[bp] += rho * py; sw[bp] += rho; cnt[bp]++;
    }
    last = -1;
  }
  let moved = 0;
  for (let p = 0; p < N; p++) {
    if (sw[p] > 1e-6 && cnt[p]) {
      const nx = sx[p] / sw[p], ny = sy[p] / sw[p];
      moved += Math.hypot(nx - PX[p], ny - PY[p]);
      PX[p] = nx; PY[p] = ny;
      PR[p] = .4 + 1.15 * Math.sqrt(Math.min(1, sw[p] / cnt[p]));
    } else place(p);
  }
  drift = moved / N * SS;
}

/* ── drawing ── */
let pointer = null;
function render() {
  if (!W) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, cv.width, cv.height);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  const path = new Path2D();
  for (let p = 0; p < N; p++) {
    const x = PX[p] * SS, y = PY[p] * SS, r = PR[p];
    path.moveTo(x + r, y);
    path.arc(x, y, r, 0, TAU);
  }
  ctx.fillStyle = css(pal.ink, .92);
  ctx.fill(path);
  /* the sun, on a ring around the table, when someone is steering it */
  if (pointer || stage.matches(':focus-visible')) {
    const R = Math.min(W, H) * .5 * (1.05 - (el - 12 * RAD) / (58 * RAD) * .75);
    const x = W / 2 + Math.cos(az) * R, y = H / 2 + Math.sin(az) * R;
    ctx.strokeStyle = css(pal.sun, 1);
    ctx.fillStyle = css(pal.sun, 1);
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.arc(x, y, 4.2, 0, TAU); ctx.fill();
    for (let i = 0; i < 8; i++) {
      const a = i * TAU / 8;
      ctx.beginPath();
      ctx.moveTo(x + Math.cos(a) * 7, y + Math.sin(a) * 7);
      ctx.lineTo(x + Math.cos(a) * 10, y + Math.sin(a) * 10);
      ctx.stroke();
    }
  }
}
let shownAz = -1, shownEl = -1;
function readout() {
  const a = Math.round(((az / RAD) % 360 + 360) % 360), e = Math.round(el / RAD);
  if (a !== shownAz) { shownAz = a; outAz.textContent = a; }
  if (e !== shownEl) { shownEl = e; outEl.textContent = e; }
  outDrift.textContent = drift.toFixed(2);
}

/* ── host ── */
let raf = 0, last = 0, seen = true, dead = false, idle = 9, readT = 0, dirty = true;
function settle(n) { for (let i = 0; i < n; i++) lloyd(); render(); readout(); }
function size(w, h) {
  if (w < 2 || h < 2 || (Math.abs(w - W) < .5 && Math.abs(h - H) < .5)) return;
  const first = !W, kx = W ? w / W : 1, ky = H ? h / H : 1;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  const odw = dw, odh = dh;
  dw = Math.ceil(W / SS); dh = Math.ceil(H / SS);
  dens = new Float32Array(dw * dh);
  if (first) { scene(); shade(); resize(N); settle(calm ? 48 : 2); return; }
  for (const s of stones) { s.x *= dw / odw; s.y *= dh / odh; }
  for (let p = 0; p < N; p++) { PX[p] *= kx; PY[p] *= ky; }
  shade();
  settle(calm ? 30 : 1);
}
function kick() {
  if (dead || raf || calm || !seen || document.hidden) return;
  last = 0;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) return;
  const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
  last = now;
  idle += dt;
  if (orbit && !pointer && idle > 1.5) { az += dt * .16 * Math.min(1, (idle - 1.5) / 2); dirty = true; }
  if (dirty) { shade(); dirty = false; }
  lloyd();
  render();
  readT += dt;
  if (readT > .15) { readT = 0; readout(); }
  raf = requestAnimationFrame(frame);
}
let rz = 0;
const ro = new ResizeObserver(([e]) => {
  const { width, height } = e.contentRect;
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; size(width, height); });
});
ro.observe(cv);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => { calm = mq.matches; calmUI(); if (calm) { shade(); settle(30); } kick(); };
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => { theme(); render(); });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  cancelAnimationFrame(rz);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}

/* ── input ── */
function relight() {
  dirty = true;
  idle = 0;
  if (calm) { shade(); dirty = false; settle(24); }
  else readout();
}
function sunAt(e) {
  const r = stage.getBoundingClientRect();
  const x = e.clientX - r.left - W / 2, y = e.clientY - r.top - H / 2;
  az = Math.atan2(y, x);
  const k = Math.min(1, Math.hypot(x / (W / 2), y / (H / 2)));
  el = (70 - 58 * k) * RAD;
}
stage.addEventListener('pointermove', (e) => {
  if (calm && !(e.buttons & 1)) return;
  pointer = e.pointerId;
  sunAt(e);
  relight();
});
stage.addEventListener('pointerdown', (e) => { if (e.button === 0) { pointer = e.pointerId; sunAt(e); relight(); } });
stage.addEventListener('pointerleave', () => { pointer = null; idle = 0; render(); });
stage.addEventListener('keydown', (e) => {
  const s = e.shiftKey ? 15 : 5;
  if (e.key === 'ArrowLeft') az -= s * RAD;
  else if (e.key === 'ArrowRight') az += s * RAD;
  else if (e.key === 'ArrowUp') el = Math.min(70 * RAD, el + s * RAD);
  else if (e.key === 'ArrowDown') el = Math.max(12 * RAD, el - s * RAD);
  else if (e.key === 'Enter' || e.key === ' ') { fresh(); e.preventDefault(); return; }
  else return;
  e.preventDefault();
  relight();
  live.textContent = 'Sun at ' + Math.round(((az / RAD) % 360 + 360) % 360) + ' degrees, ' + Math.round(el / RAD) + ' up.';
});
stage.addEventListener('focus', () => render());
stage.addEventListener('blur', () => render());
function fresh() {
  seed = 1 + ((Math.random() * 9998) | 0);
  scene();
  shade();
  sampler = rng(seed);
  for (let p = 0; p < N; p++) place(p);
  live.textContent = stones.length + ' new pebbles, study number ' + seed + '.';
  if (calm) settle(48); else { render(); kick(); }
}
root.querySelector('.fxg-stipple__btn--go').addEventListener('click', fresh);
btnOrbit.addEventListener('click', () => {
  orbit = !orbit;
  btnOrbit.setAttribute('aria-pressed', String(orbit));
  live.textContent = orbit ? 'The sun drifts round when left alone.' : 'The sun stays where you leave it.';
});
radios.forEach((r) => r.addEventListener('change', () => {
  if (!r.checked) return;
  resize(+r.value);
  live.textContent = (+r.value).toLocaleString('en-US') + ' dots.';
  if (calm) settle(40); else render();
}));
/* reduced motion: the sun never wanders on its own, so the orbit switch stands down */
function calmUI() {
  btnOrbit.disabled = calm;
  if (calm) { orbit = false; btnOrbit.setAttribute('aria-pressed', 'false'); }
}
calmUI();

theme();
{
  const r = cv.getBoundingClientRect();
  size(r.width, r.height);
}
kick();

css:
@property --fxg-quilt-a {
  syntax: '<angle>';
  inherits: false;
  initial-value: 45deg;
}
@property --fxg-quilt-turn {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
.fxg-quilt {
  /* Re-theme with these four; ochre and blush are mixed from them. */
  --fxg-quilt-paper: oklch(0.948 0.022 82);
  --fxg-quilt-ink: oklch(0.27 0.025 50);
  --fxg-quilt-warm: oklch(0.6 0.15 38);
  --fxg-quilt-cool: oklch(0.66 0.07 160);

  --fxg-quilt-ochre: color-mix(in oklch, var(--fxg-quilt-warm) 38%, oklch(0.83 0.15 88));
  --fxg-quilt-blush: color-mix(in oklch, var(--fxg-quilt-warm) 30%, var(--fxg-quilt-paper));
  --fxg-quilt-muted: color-mix(in oklch, var(--fxg-quilt-ink) 58%, var(--fxg-quilt-paper));
  --fxg-quilt-line: color-mix(in oklch, var(--fxg-quilt-ink) 14%, transparent);
  --fxg-quilt-hover: color-mix(in oklch, var(--fxg-quilt-ochre) 22%, var(--fxg-quilt-paper));
  --fxg-quilt-out: cubic-bezier(.16, 1, .3, 1);
  --fxg-quilt-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" "board board" "bar bar";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 10px 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 10 / 9;
  min-block-size: 300px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxg-quilt-paper);
  color: var(--fxg-quilt-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxg-quilt-line);

  & .fxg-quilt__head { grid-area: head; min-inline-size: 0; }
  & .fxg-quilt__eyebrow {
    margin: 0 0 3px;
    font-size: 9.5px;
    font-weight: 650;
    letter-spacing: .15em;
    text-transform: uppercase;
    color: var(--fxg-quilt-warm);
  }
  & .fxg-quilt__title {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin: 0;
    font-size: clamp(20px, 6.6cqi, 28px);
    font-weight: 800;
    line-height: 1;
    letter-spacing: -0.04em;
    text-wrap: balance;
  }
  & .fxg-quilt__title span {
    font: 500 10px/1 ui-monospace, Menlo, monospace;
    letter-spacing: 0;
    font-variant-numeric: tabular-nums;
    color: var(--fxg-quilt-muted);
  }
  & .fxg-quilt__read {
    grid-area: read;
    display: flex;
    gap: 14px;
    align-self: end;
    margin: 0;
  }
  & .fxg-quilt__read div {
    display: grid;
    gap: 3px;
    text-align: end;
    transition: opacity .6s var(--fxg-quilt-out) calc(var(--i) * 70ms + 120ms), translate .8s var(--fxg-quilt-out) calc(var(--i) * 70ms + 120ms);
    @starting-style { opacity: 0; translate: 0 5px; }
  }
  & .fxg-quilt__read dt {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-quilt-muted);
  }
  & .fxg-quilt__read dd {
    margin: 0;
    font: 650 clamp(13px, 4cqi, 16px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }

  & .fxg-quilt__board {
    grid-area: board;
    display: grid;
    grid-template: minmax(0, 1fr) / minmax(0, 1fr);
    min-block-size: 0;
    padding: 3px;
    border-radius: 6px;
    background: var(--fxg-quilt-paper);
    box-shadow: 0 0 0 1px var(--fxg-quilt-line), 0 14px 26px -20px color-mix(in oklch, var(--fxg-quilt-ink) 70%, transparent);
  }
  & .fxg-quilt__split {
    display: grid;
    gap: 3px;
    min-inline-size: 0;
    min-block-size: 0;
  }
  & .fxg-quilt__split[data-dir="col"] { grid-template-columns: var(--p); }
  & .fxg-quilt__split[data-dir="row"] { grid-template-rows: var(--p); }
  & .fxg-quilt__tile {
    --q: calc(var(--fxg-quilt-a) + var(--fxg-quilt-turn));
    --px: clamp(0%, 50% + 71% * cos(var(--q)), 100%);
    --py: clamp(0%, 50% + 71% * sin(var(--q)), 100%);
    container-type: size;
    position: relative;
    display: block;
    inline-size: 100%;
    block-size: 100%;
    min-inline-size: 0;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 2px;
    background: var(--c2);
    cursor: pointer;
    outline: none;
    clip-path: inset(0 round 2px);
    transition:
      clip-path .75s var(--fxg-quilt-out) calc(var(--i, 0) * 24ms),
      --fxg-quilt-a .9s var(--fxg-quilt-spring),
      --fxg-quilt-turn .6s var(--fxg-quilt-spring),
      filter .25s var(--fxg-quilt-out);
    @starting-style { clip-path: inset(50% 50% 50% 50% round 40%); }
  }
  & .fxg-quilt__tile[data-m="arc"] { background: radial-gradient(circle at var(--px) var(--py), var(--c1) 0 calc(100cqmin - .5px), var(--c2) 100cqmin); }
  & .fxg-quilt__tile[data-m="half"] { background: linear-gradient(var(--q), var(--c1) 50%, var(--c2) 0); }
  & .fxg-quilt__tile[data-m="stripes"] { background: repeating-linear-gradient(var(--q), var(--c1) 0 6cqmin, var(--c2) 6cqmin 12cqmin); }
  & .fxg-quilt__tile[data-m="rings"] { background: repeating-radial-gradient(circle at var(--px) var(--py), var(--c1) 0 9cqmin, var(--c2) 9cqmin 18cqmin); }
  & .fxg-quilt__tile[data-m="dots"] {
    background: radial-gradient(circle, var(--c1) 0 27%, transparent 29%) calc(6cqmin + 6cqmin * cos(var(--q))) calc(6cqmin + 6cqmin * sin(var(--q))) / 24cqmin 24cqmin, var(--c2);
  }
  & .fxg-quilt__tile[data-m="pin"] { background: conic-gradient(from var(--q), var(--c1) 0 25%, var(--c2) 0 50%, var(--c1) 0 75%, var(--c2) 0); }
  & .fxg-quilt__tile[data-m="moon"] {
    background:
      radial-gradient(circle, transparent 0 34cqmin, var(--c2) calc(34cqmin + .5px)),
      linear-gradient(var(--q), var(--c1) 50%, var(--c3) 0);
  }
  & .fxg-quilt__tile:hover { filter: brightness(1.04) saturate(1.06); }
  & .fxg-quilt__tile:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxg-quilt-paper), inset 0 0 0 4px var(--fxg-quilt-ink);
    z-index: 1;
  }
  /* split tool: a dashed cut previews exactly where the click will divide the panel */
  & .fxg-quilt__tile::after {
    content: "";
    position: absolute;
    border: 0 dashed white;
    mix-blend-mode: difference;
    opacity: 0;
    pointer-events: none;
    transition: opacity .2s var(--fxg-quilt-out);
  }
  & .fxg-quilt__tile[data-cut="v"]::after { inset-block: 5px; inset-inline-start: calc(var(--r, .5) * 100% - 1px); border-inline-start-width: 2px; }
  & .fxg-quilt__tile[data-cut="h"]::after { inset-inline: 5px; inset-block-start: calc(var(--r, .5) * 100% - 1px); border-block-start-width: 2px; }
  &[data-tool="split"] .fxg-quilt__tile:is(:hover, :focus-visible)::after { opacity: 1; }
  /* turn tool: the panel previews its quarter turn */
  &[data-tool="turn"] .fxg-quilt__tile:is(:hover, :focus-visible) { --fxg-quilt-turn: 90deg; }
  /* merge tool: the pair that would fuse is outlined, found with :has() */
  &[data-tool="merge"] .fxg-quilt__split:has(> .fxg-quilt__tile:is(:hover, :focus-visible)) {
    outline: 2px dashed var(--fxg-quilt-ink);
    outline-offset: 1px;
    border-radius: 2px;
    z-index: 1;
  }
  &[data-tool="turn"] .fxg-quilt__board { cursor: alias; }

  & .fxg-quilt__bar {
    grid-area: bar;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 8px;
  }
  & .fxg-quilt__tools {
    display: flex;
    gap: 2px;
    justify-self: start;
    margin: 0;
    padding: 2px;
    border: 0;
    border-radius: 999px;
    background: color-mix(in oklch, var(--fxg-quilt-ink) 7%, var(--fxg-quilt-paper));
    box-shadow: inset 0 0 0 1px var(--fxg-quilt-line);
  }
  & .fxg-quilt__tools label {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 6px 10px 6px 8px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    color: var(--fxg-quilt-muted);
    cursor: pointer;
    transition: background-color .3s var(--fxg-quilt-out), color .3s var(--fxg-quilt-out), scale .45s var(--fxg-quilt-spring);
  }
  & .fxg-quilt__tools input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & .fxg-quilt__tools svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.4;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxg-quilt__tools label:hover { color: var(--fxg-quilt-ink); background: var(--fxg-quilt-hover); }
  & .fxg-quilt__tools label:has(:checked) { background: var(--fxg-quilt-ink); color: var(--fxg-quilt-paper); }
  & .fxg-quilt__tools label:has(:active) { scale: .94; }
  & .fxg-quilt__tools label:has(:focus-visible) { outline: 2px solid var(--fxg-quilt-warm); outline-offset: 1px; }
  & .fxg-quilt__new {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    block-size: 30px;
    padding: 0 12px 0 9px;
    border: 0;
    border-radius: 999px;
    background: var(--fxg-quilt-warm);
    color: var(--fxg-quilt-paper);
    font: 650 11.5px/1 system-ui, sans-serif;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color .25s var(--fxg-quilt-out), scale .45s var(--fxg-quilt-spring);
  }
  & .fxg-quilt__new:hover { background: color-mix(in oklch, var(--fxg-quilt-warm) 82%, var(--fxg-quilt-ink)); }
  & .fxg-quilt__new:active { scale: .94; }
  & .fxg-quilt__new:focus-visible { outline: 2px solid var(--fxg-quilt-ink); outline-offset: 2px; }
  & .fxg-quilt__new svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.4;
    stroke-linecap: round;
  }
  & .fxg-quilt__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: 0;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @container (max-width: 350px) {
    & .fxg-quilt__tools span { display: none; }
    & .fxg-quilt__tools label { padding: 7px 9px; }
  }
  @container (max-width: 290px) {
    & .fxg-quilt__new span { display: none; }
    & .fxg-quilt__new { padding: 0 9px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxg-quilt {
    & .fxg-quilt__tile,
    & .fxg-quilt__tile::after,
    & .fxg-quilt__read div,
    & .fxg-quilt__tools label,
    & .fxg-quilt__new { transition: none; }
    & .fxg-quilt__tile { @starting-style { clip-path: inset(0 round 2px); } }
  }
}

js:
/* Quilt — recursive subdivision as real layout. Each split is a two-track CSS grid
   (minmax(0, r fr) minmax(0, (1 - r) fr)) with r drawn from thirds, halves and the
   golden cut; cells split across their longer side with a probability that falls
   with depth and area. A leaf is a button and a size container: its motif is a
   gradient whose angle and anchor come from a registered <angle>, with the anchor
   placed by CSS cos()/sin(), so a quarter turn is a spring transition, not a redraw.
   Split, turn and merge rebuild only the touched subtree. */
const board = root.querySelector('.fxg-quilt__board');
const live = root.querySelector('p.fxg-quilt__sr');
const tools = [...root.querySelectorAll('.fxg-quilt__tools input')];
const $ = (n) => root.querySelector('[data-k="' + n + '"]');
const outSeed = $('seed'), outPanels = $('panels'), outDepth = $('depth');
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const INKS = ['paper', 'ink', 'warm', 'cool', 'ochre', 'blush'];
const INK_W = [3, 2.2, 2, 1.6, 1.4, 1];
const NAMES = { paper: 'oat', ink: 'ink', warm: 'clay', cool: 'sage', ochre: 'ochre', blush: 'blush' };
const MOTIFS = [['arc', 'quarter arc', 3], ['half', 'half and half', 2], ['stripes', 'stripes', 1.4], ['rings', 'rings', 1.2], ['dots', 'dots', 1.2], ['pin', 'pinwheel', 1.4], ['moon', 'moon', 1]];
const RATIOS = [1 / 3, .382, .5, .618, 2 / 3];
let seed = 731, tree = null, tool = 'split';
const nodeOf = new WeakMap();

function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}
let rnd = rng(seed);
function pickW(items, weights, r) {
  let t = r() * weights.reduce((a, b) => a + b, 0);
  for (let i = 0; i < items.length; i++) { t -= weights[i]; if (t <= 0) return items[i]; }
  return items[items.length - 1];
}
function dress(n, r) {
  const m = pickW(MOTIFS, MOTIFS.map((x) => x[2]), r);
  n.m = m[0]; n.label = m[1];
  n.c1 = pickW(INKS, INK_W, r);
  do n.c2 = pickW(INKS, INK_W, r); while (n.c2 === n.c1);
  do n.c3 = pickW(INKS, INK_W, r); while (n.c3 === n.c1 || n.c3 === n.c2);
  n.a = 45 + 90 * ((r() * 4) | 0);
  return n;
}
function grow(parent, w, h, depth, r) {
  const n = { parent, depth, kids: null };
  const p = [1, .96, .82, .6, .34, .1][depth] || 0;
  if (r() < p && w * h > .016) {
    n.dir = w > h * 1.15 ? 'col' : h > w * 1.15 ? 'row' : (r() < .5 ? 'col' : 'row');
    n.ratio = RATIOS[(r() * RATIOS.length) | 0];
    const a = n.ratio, b = 1 - a;
    n.kids = n.dir === 'col'
      ? [grow(n, w * a, h, depth + 1, r), grow(n, w * b, h, depth + 1, r)]
      : [grow(n, w, h * a, depth + 1, r), grow(n, w, h * b, depth + 1, r)];
  } else dress(n, r);
  return n;
}

/* ── DOM ── */
function make(n) {
  let el;
  if (n.kids) {
    el = document.createElement('div');
    el.className = 'fxg-quilt__split';
    el.dataset.dir = n.dir;
    el.style.setProperty('--p', 'minmax(0, ' + n.ratio.toFixed(4) + 'fr) minmax(0, ' + (1 - n.ratio).toFixed(4) + 'fr)');
    n.kids.forEach((k) => el.appendChild(make(k)));
  } else {
    el = document.createElement('button');
    el.type = 'button';
    el.className = 'fxg-quilt__tile';
    el.tabIndex = -1;
    el.dataset.m = n.m;
    el.style.setProperty('--c1', 'var(--fxg-quilt-' + n.c1 + ')');
    el.style.setProperty('--c2', 'var(--fxg-quilt-' + n.c2 + ')');
    el.style.setProperty('--c3', 'var(--fxg-quilt-' + n.c3 + ')');
    el.style.setProperty('--fxg-quilt-a', n.a + 'deg');
    label(el, n);
  }
  n.el = el;
  nodeOf.set(el, n);
  return el;
}
function label(el, n) {
  el.setAttribute('aria-label', n.label + ', ' + NAMES[n.c1] + ' on ' + NAMES[n.c2] + ', turned ' + (((n.a - 45) % 360 + 360) % 360) + ' degrees');
}
const tiles = () => [...board.querySelectorAll('.fxg-quilt__tile')];
function stats() {
  let leaves = 0, depth = 0;
  (function walk(n) { if (n.kids) n.kids.forEach(walk); else { leaves++; depth = Math.max(depth, n.depth); } })(tree);
  outPanels.textContent = leaves;
  outDepth.textContent = depth;
  return leaves;
}
let focusEl = null;
function rove(el, move) {
  if (focusEl && focusEl !== el && focusEl.isConnected) focusEl.tabIndex = -1;
  focusEl = el;
  if (!el) return;
  el.tabIndex = 0;
  if (move) el.focus({ preventScroll: true });
}
function quilt(announce) {
  rnd = rng(seed);
  const r = board.getBoundingClientRect();
  tree = grow(null, (r.width || 4) / (r.height || 3), 1, 0, rng(seed * 7 + 1));
  board.replaceChildren(make(tree));
  tiles().forEach((t, i) => t.style.setProperty('--i', i));
  rove(tiles()[0], false);
  outSeed.textContent = 'No. ' + String(seed).padStart(4, '0');
  const n = stats();
  if (announce) live.textContent = 'New quilt, number ' + seed + ', ' + n + ' panels.';
}

/* ── actions ── */
function nudge(el) {
  if (calm) return;
  el.animate([{ translate: '0 0' }, { translate: '-3px 0' }, { translate: '3px 0' }, { translate: '-1.5px 0' }, { translate: '0 0' }],
    { duration: 300, easing: 'cubic-bezier(.36, .07, .19, .97)' });
}
function preview(el) {
  const n = nodeOf.get(el);
  if (!n || n.kids) return;
  const r = el.getBoundingClientRect();
  if (!n.cut) {
    n.cut = r.width >= r.height ? 'v' : 'h';
    n.r = RATIOS[(Math.random() * RATIOS.length) | 0];
  }
  el.dataset.cut = n.cut;
  el.style.setProperty('--r', n.r);
}
function split(el, kb) {
  const n = nodeOf.get(el), r = el.getBoundingClientRect();
  preview(el);
  const side = (n.cut === 'v' ? r.width : r.height) * Math.min(n.r, 1 - n.r);
  if (side < 18 || n.depth > 8) { nudge(el); live.textContent = 'That panel is too small to split.'; return; }
  n.dir = n.cut === 'v' ? 'col' : 'row';
  n.ratio = n.r;
  n.kids = [dress({ parent: n, depth: n.depth + 1, kids: null }, rnd), dress({ parent: n, depth: n.depth + 1, kids: null }, rnd)];
  n.cut = null;
  const fresh = make(n);
  el.replaceWith(fresh);
  const kids = [...fresh.children];
  kids.forEach((k, i) => k.style.setProperty('--i', i));
  rove(kids[0], kb);
  const c = stats();
  live.textContent = 'Split into ' + n.kids[0].label + ' and ' + n.kids[1].label + '. ' + c + ' panels.';
}
function turn(el, quiet) {
  const n = nodeOf.get(el);
  n.a += 90;
  el.style.setProperty('--fxg-quilt-a', n.a + 'deg');
  label(el, n);
  if (!quiet) live.textContent = 'Turned the ' + n.label + '.';
}
function merge(el, kb) {
  const n = nodeOf.get(el), p = n && n.parent;
  if (!p) { nudge(el); live.textContent = 'This is the whole quilt; there is nothing to merge with.'; return; }
  p.kids = null; p.cut = null;
  dress(p, rnd);
  const fresh = make(p);
  p.el && p.el.isConnected ? p.el.replaceWith(fresh) : null;
  rove(fresh, kb);
  const c = stats();
  live.textContent = 'Merged into one ' + p.label + '. ' + c + ' panels.';
}
function act(el, how, kb) {
  lastUser = performance.now();
  if (how === 'split') split(el, kb);
  else if (how === 'turn') turn(el);
  else merge(el, kb);
}

/* ── input ── */
board.addEventListener('pointerover', (e) => {
  const el = e.target.closest('.fxg-quilt__tile');
  if (el) { preview(el); lastUser = performance.now(); }
});
board.addEventListener('click', (e) => {
  const el = e.target.closest('.fxg-quilt__tile');
  if (!el) return;
  const kb = e.detail === 0;
  rove(el, false);
  act(el, e.shiftKey ? 'merge' : e.altKey ? 'turn' : tool, kb);
});
board.addEventListener('focusin', (e) => {
  const el = e.target.closest('.fxg-quilt__tile');
  if (el) { rove(el, false); preview(el); }
});
function neighbour(el, dx, dy) {
  const a = el.getBoundingClientRect(), ax = a.left + a.width / 2, ay = a.top + a.height / 2;
  let best = null, bd = Infinity;
  for (const t of tiles()) {
    if (t === el) continue;
    const b = t.getBoundingClientRect(), bx = b.left + b.width / 2, by = b.top + b.height / 2;
    const fx = dx ? (dx > 0 ? b.left >= a.right - 1 : b.right <= a.left + 1) : true;
    const fy = dy ? (dy > 0 ? b.top >= a.bottom - 1 : b.bottom <= a.top + 1) : true;
    if (!fx || !fy) continue;
    /* overlap on the cross axis counts for more than distance along the move */
    const along = dx ? Math.abs(bx - ax) : Math.abs(by - ay);
    const across = dx ? Math.max(0, Math.max(a.top, b.top) - Math.min(a.bottom, b.bottom)) + Math.abs(by - ay) * .25
                      : Math.max(0, Math.max(a.left, b.left) - Math.min(a.right, b.right)) + Math.abs(bx - ax) * .25;
    const d = along + across * 3;
    if (d < bd) { bd = d; best = t; }
  }
  return best;
}
board.addEventListener('keydown', (e) => {
  const el = e.target.closest('.fxg-quilt__tile');
  if (!el) return;
  const dirs = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] };
  if (dirs[e.key]) {
    const t = neighbour(el, dirs[e.key][0], dirs[e.key][1]);
    if (t) rove(t, true); else nudge(el);
  } else if (e.key === 'Home') rove(tiles()[0], true);
  else if (e.key === 'End') { const all = tiles(); rove(all[all.length - 1], true); }
  else if (e.key === 's' || e.key === 'S') act(el, 'split', true);
  else if (e.key === 't' || e.key === 'T') act(el, 'turn', true);
  else if (e.key === 'm' || e.key === 'M' || e.key === 'Backspace' || e.key === 'Delete') act(el, 'merge', true);
  else return;
  e.preventDefault();
});
tools.forEach((t) => t.addEventListener('change', () => {
  if (!t.checked) return;
  tool = t.value;
  root.dataset.tool = tool;
}));
root.querySelector('.fxg-quilt__new').addEventListener('click', () => {
  seed = 1 + ((Math.random() * 9998) | 0);
  quilt(true);
  lastUser = performance.now();
});

/* ── at rest, one panel at a time takes a quarter turn ── */
let seen = true, lastUser = -1e9;
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; }, { rootMargin: '40px' });
io.observe(root);
const onMq = () => { calm = mq.matches; };
mq.addEventListener('change', onMq);
function stop() { clearInterval(tick); io.disconnect(); mq.removeEventListener('change', onMq); }
const tick = setInterval(() => {
  if (!root.isConnected) return stop();
  if (calm || !seen || document.hidden || performance.now() - lastUser < 5000) return;
  if (root.matches(':hover') || root.contains(document.activeElement)) return;
  const all = tiles();
  if (all.length) turn(all[(Math.random() * all.length) | 0], true);
}, 2300);

quilt(false);

css:
.fxg-array {
  /* Re-theme with these three: the tank, the wavefronts and the beam trace. */
  --fxg-array-tank: oklch(0.175 0.022 168);
  --fxg-array-wave: oklch(0.88 0.18 148);
  --fxg-array-beam: oklch(0.8 0.15 72);

  --fxg-array-ink: color-mix(in oklch, var(--fxg-array-wave) 30%, oklch(0.97 0.01 150));
  --fxg-array-muted: color-mix(in oklch, var(--fxg-array-wave) 45%, var(--fxg-array-tank));
  --fxg-array-line: color-mix(in oklch, var(--fxg-array-wave) 18%, transparent);
  --fxg-array-chip: color-mix(in oklch, var(--fxg-array-tank) 80%, transparent);
  --fxg-array-out: cubic-bezier(.16, 1, .3, 1);
  --fxg-array-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" ". ." "panel panel";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 10 / 9;
  min-block-size: 310px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxg-array-tank);
  color: var(--fxg-array-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxg-array-line);

  & .fxg-array__cv,
  & .fxg-array__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxg-array__cv { display: block; }
  & .fxg-array__stage {
    z-index: 1;
    outline: none;
    touch-action: pan-y;
    border-radius: inherit;
    cursor: crosshair;
  }
  & .fxg-array__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxg-array-beam), inset 0 0 0 5px color-mix(in oklch, var(--fxg-array-beam) 22%, transparent);
  }
  & .fxg-array__head,
  & .fxg-array__read {
    position: relative;
    z-index: 2;
    margin: 0;
    pointer-events: none;
    text-shadow: 0 0 6px var(--fxg-array-tank), 0 0 12px var(--fxg-array-tank);
  }
  & .fxg-array__head { grid-area: head; min-inline-size: 0; }
  & .fxg-array__eyebrow {
    display: flex;
    flex-wrap: wrap;
    gap: 0 6px;
    margin: 0 0 4px;
    font: 500 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .06em;
    text-transform: uppercase;
    color: var(--fxg-array-muted);
  }
  & .fxg-array__eyebrow span:last-child { color: var(--fxg-array-beam); font-variant-numeric: tabular-nums; }
  & .fxg-array__title {
    margin: 0;
    font: 700 clamp(19px, 6.4cqi, 27px)/1 ui-monospace, Menlo, monospace;
    letter-spacing: -0.04em;
    text-wrap: balance;
  }
  & .fxg-array__read {
    grid-area: read;
    display: grid;
    gap: 5px;
    align-self: start;
    text-align: end;
  }
  & .fxg-array__read div {
    display: flex;
    align-items: baseline;
    justify-content: flex-end;
    gap: 8px;
    transition: opacity .6s var(--fxg-array-out) calc(var(--i) * 70ms + 150ms), translate .8s var(--fxg-array-out) calc(var(--i) * 70ms + 150ms);
    @starting-style { opacity: 0; translate: 6px 0; }
  }
  & .fxg-array__read dt {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: var(--fxg-array-muted);
  }
  & .fxg-array__read dt span { text-transform: none; letter-spacing: .02em; }
  & .fxg-array__read dd {
    margin: 0;
    min-inline-size: 6ch;
    font: 600 13px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxg-array__lobes dd { transition: color .3s; }
  &[data-grating] .fxg-array__lobes dd { color: var(--fxg-array-beam); }

  & .fxg-array__panel {
    grid-area: panel;
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    padding: 7px;
    border-radius: 12px;
    background: var(--fxg-array-chip);
    backdrop-filter: blur(8px);
    box-shadow: inset 0 0 0 1px var(--fxg-array-line);
  }
  & .fxg-array__count {
    display: flex;
    align-items: center;
    gap: 2px;
    padding: 2px;
    border-radius: 999px;
    box-shadow: inset 0 0 0 1px var(--fxg-array-line);
  }
  & .fxg-array__count button {
    display: grid;
    place-items: center;
    inline-size: 26px;
    block-size: 26px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: var(--fxg-array-ink);
    cursor: pointer;
    transition: background-color .2s var(--fxg-array-out), scale .4s var(--fxg-array-spring);
  }
  & .fxg-array__count button:hover:not(:disabled) { background: color-mix(in oklch, var(--fxg-array-wave) 16%, transparent); }
  & .fxg-array__count button:active:not(:disabled) { scale: .88; }
  & .fxg-array__count button:disabled { opacity: .35; cursor: default; }
  & .fxg-array__count button:focus-visible { outline: 2px solid var(--fxg-array-beam); outline-offset: 1px; }
  & .fxg-array__count svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.6;
    stroke-linecap: round;
  }
  & .fxg-array__count output {
    min-inline-size: 2.4ch;
    font: 700 13px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    text-align: center;
  }
  & .fxg-array__space {
    display: grid;
    grid-template-columns: auto minmax(40px, 1fr) auto;
    align-items: center;
    gap: 8px;
    min-inline-size: 0;
  }
  & .fxg-array__name { font: italic 600 13px/1 ui-serif, Georgia, serif; color: var(--fxg-array-muted); }
  & .fxg-array__space input {
    inline-size: 100%;
    margin: 0;
    accent-color: var(--fxg-array-wave);
    cursor: pointer;
  }
  & .fxg-array__space input:focus-visible { outline: 2px solid var(--fxg-array-beam); outline-offset: 3px; border-radius: 4px; }
  & .fxg-array__space output {
    min-inline-size: 5ch;
    font: 600 11.5px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    text-align: end;
  }
  & .fxg-array__new {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    block-size: 30px;
    padding: 0 12px 0 9px;
    border: 0;
    border-radius: 999px;
    background: var(--fxg-array-wave);
    color: var(--fxg-array-tank);
    font: 700 11.5px/1 system-ui, sans-serif;
    cursor: pointer;
    transition: background-color .25s var(--fxg-array-out), scale .45s var(--fxg-array-spring);
  }
  & .fxg-array__new:hover { background: color-mix(in oklch, var(--fxg-array-wave) 75%, white); }
  & .fxg-array__new:active { scale: .94; }
  & .fxg-array__new:focus-visible { outline: 2px solid var(--fxg-array-beam); outline-offset: 2px; }
  & .fxg-array__new svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.5;
    stroke-linecap: round;
  }
  & .fxg-array__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @container (max-width: 340px) {
    & .fxg-array__new span { display: none; }
    & .fxg-array__new { padding: 0 9px; }
    & .fxg-array__panel { gap: 7px; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxg-array {
    & .fxg-array__read div,
    & .fxg-array__count button,
    & .fxg-array__new,
    & .fxg-array__lobes dd { transition: none; }
  }
}

js:
/* Beamformer — superposition from N point emitters. With the emitter phasors
     P_i(x) = e^{i k r_i} / sqrt(r_i + r0)
   cached per field cell, steering to angle theta is one complex multiply per emitter
   (phase phi_i = k (e_i - c) . u_theta, which lines every wavefront up along u), and
   the travelling picture each frame is Re(S e^{-i w t}) = S_re cos wt + S_im sin wt.
   The array factor |sum e^{i(phi_i - k (e_i - c) . u)}| / N is sampled round the
   circle for the -3 dB beamwidth and for grating lobes, which appear once the spacing
   passes lambda / (1 + |sin theta|). */
const cv = root.querySelector('.fxg-array__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxg-array__stage');
const probe = root.querySelector('.fxg-array__probe');
const panel = root.querySelector('.fxg-array__panel');
const live = root.querySelector('p.fxg-array__sr');
const dIn = root.querySelector('.fxg-array__space input');
const steps = [...root.querySelectorAll('.fxg-array__count button')];
const $ = (n) => root.querySelector('[data-k="' + n + '"]');
const out = { geo: $('geo'), seed: $('seed'), steer: $('steer'), bw: $('bw'), lobes: $('lobes'), n: $('n'), d: $('d') };
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2, RAD = Math.PI / 180, CELL = 2.5, AFN = 720, OMEGA = TAU * .85;
const GEOS = ['Line', 'Arc', 'Ring', 'Scatter'];
let W = 0, H = 0, DPR = 1, gw = 0, gh = 0;
let N = 8, D = .5, geo = 0, seed = 412;
let lam = 28, k = TAU / 28, cx = 0, cy = 0;
let ex = new Float32Array(0), ey = new Float32Array(0);
let pre = null, pim = null, Sre = null, Sim = null, gain = 1;
let theta = 0, target = 0;
const af = new Float32Array(AFN);
const off = document.createElement('canvas'), ox = off.getContext('2d');
let img = null;
const lut = new Uint8ClampedArray(256 * 3);
const pal = {};

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
function theme() {
  pal.tank = rgb('--fxg-array-tank');
  pal.wave = rgb('--fxg-array-wave');
  pal.beam = rgb('--fxg-array-beam');
  const deep = pal.tank.map((v) => v * .45);
  /* trough -> still water -> crest, with the crest kept narrow and bright */
  for (let i = 0; i < 256; i++) {
    const t = i / 255 * 2 - 1;
    let c;
    if (t < 0) { const m = -t; c = pal.tank.map((v, j) => v + (deep[j] - v) * m); }
    else { const m = Math.pow(t, 1.5); c = pal.tank.map((v, j) => v + (pal.wave[j] - v) * m); }
    lut[i * 3] = c[0]; lut[i * 3 + 1] = c[1]; lut[i * 3 + 2] = c[2];
  }
}
function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}

/* ── geometry, in wavelengths, then fitted to the tank ── */
function layout() {
  const r = rng(seed * 3 + geo), pts = [];
  if (geo === 0) for (let i = 0; i < N; i++) pts.push([(i - (N - 1) / 2) * D, 0]);
  else if (geo === 1) {
    const R = Math.max(1.2, N * D / 1.4);
    for (let i = 0; i < N; i++) { const b = (i - (N - 1) / 2) * D / R; pts.push([R * Math.sin(b), R * (1 - Math.cos(b))]); }
  } else if (geo === 2) {
    const R = Math.max(.35, N * D / TAU);
    for (let i = 0; i < N; i++) { const b = i / N * TAU; pts.push([R * Math.cos(b), R * Math.sin(b)]); }
  } else {
    const R = Math.max(.8, Math.sqrt(N) * D * .9);
    for (let t = 0; pts.length < N && t < 4000; t++) {
      const a = r() * TAU, q = Math.sqrt(r()) * R, x = Math.cos(a) * q, y = Math.sin(a) * q * .6;
      if (pts.every((p) => Math.hypot(p[0] - x, p[1] - y) > D * .75)) pts.push([x, y]);
    }
    while (pts.length < N) pts.push([(r() - .5) * R, (r() - .5) * R * .6]);
  }
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const p of pts) { x0 = Math.min(x0, p[0]); x1 = Math.max(x1, p[0]); y0 = Math.min(y0, p[1]); y1 = Math.max(y1, p[1]); }
  const base = Math.max(16, Math.min(32, Math.min(W, H) / 11));
  lam = Math.min(base, W * .8 / Math.max(.01, x1 - x0));
  k = TAU / lam;
  const bottom = panel.offsetTop - 18;
  const offX = W / 2 - (x0 + x1) / 2 * lam;
  const offY = geo === 2 ? Math.min(bottom - (y1 - y0) / 2 * lam, H * .6) - (y0 + y1) / 2 * lam : bottom - y1 * lam;
  ex = new Float32Array(N); ey = new Float32Array(N);
  cx = 0; cy = 0;
  for (let i = 0; i < N; i++) {
    ex[i] = offX + pts[i][0] * lam; ey[i] = offY + pts[i][1] * lam;
    cx += ex[i] / N; cy += ey[i] / N;
  }
  /* cache e^{ikr}/sqrt(r + r0) for every cell and emitter */
  const cells = gw * gh;
  pre = new Float32Array(cells * N); pim = new Float32Array(cells * N);
  let acc = 0;
  for (let j = 0; j < gh; j++) {
    for (let i = 0; i < gw; i++) {
      const px = (i + .5) * CELL, py = (j + .5) * CELL, c = j * gw + i;
      for (let e = 0; e < N; e++) {
        const r = Math.hypot(px - ex[e], py - ey[e]), a = 1 / Math.sqrt(r / lam + .35);
        pre[c * N + e] = Math.cos(k * r) * a; pim[c * N + e] = Math.sin(k * r) * a;
        acc += a;
      }
    }
  }
  /* exposure: a beam of N in phase reaches about N times one emitter's mean amplitude */
  gain = 1.5 / (acc / cells / N * Math.sqrt(N) * 1.6);
  out.geo.textContent = GEOS[geo];
  out.seed.textContent = 'No. ' + String(seed).padStart(4, '0');
  out.n.textContent = N;
  out.d.textContent = D.toFixed(2) + 'λ';
  dIn.value = D;
  steps[0].disabled = N <= 2; steps[1].disabled = N >= 16;
}
const phr = new Float32Array(16), phi = new Float32Array(16), phase = new Float32Array(16);
function steer() {
  const ux = Math.sin(theta), uy = -Math.cos(theta);
  for (let e = 0; e < N; e++) {
    phase[e] = k * ((ex[e] - cx) * ux + (ey[e] - cy) * uy);
    phr[e] = Math.cos(phase[e]); phi[e] = Math.sin(phase[e]);
  }
  const cells = gw * gh;
  for (let c = 0; c < cells; c++) {
    let re = 0, im = 0;
    const o = c * N;
    for (let e = 0; e < N; e++) {
      const a = pre[o + e], b = pim[o + e];
      re += a * phr[e] - b * phi[e];
      im += a * phi[e] + b * phr[e];
    }
    Sre[c] = re; Sim[c] = im;
  }
  /* array factor round the circle, angle measured from straight up */
  let peak = 0;
  for (let s = 0; s < AFN; s++) {
    const p = s / AFN * TAU, vx = Math.sin(p), vy = -Math.cos(p);
    let re = 0, im = 0;
    for (let e = 0; e < N; e++) {
      const q = phase[e] - k * ((ex[e] - cx) * vx + (ey[e] - cy) * vy);
      re += Math.cos(q); im += Math.sin(q);
    }
    af[s] = Math.hypot(re, im) / N;
    peak = Math.max(peak, af[s]);
  }
}
let bwDeg = 0, lobes = 0;
function measure() {
  const s0 = Math.round(((theta / TAU) % 1 + 1) % 1 * AFN) % AFN;
  /* walk out from the steer direction to the half-power points */
  let l = 0, r = 0;
  while (l < AFN / 2 && af[(s0 - l + AFN) % AFN] ** 2 >= .5) l++;
  while (r < AFN / 2 && af[(s0 + r) % AFN] ** 2 >= .5) r++;
  bwDeg = (l + r - 1) * 360 / AFN;
  /* grating lobes: other full-height maxima in the forward half */
  lobes = 0;
  for (let s = 0; s < AFN; s++) {
    const deg = s * 360 / AFN, fwd = deg <= 90 || deg >= 270;
    if (!fwd) continue;
    const a = af[s], aL = af[(s - 1 + AFN) % AFN], aR = af[(s + 1) % AFN];
    const dist = Math.min(Math.abs(s - s0), AFN - Math.abs(s - s0));
    if (a >= aL && a > aR && a * a > .5 && dist > Math.max(l, r) + 2) lobes++;
  }
}

/* ── drawing ── */
let clock = 0;
function render() {
  if (!W) return;
  const d = img.data, cells = gw * gh, cw = Math.cos(OMEGA * clock), sn = Math.sin(OMEGA * clock);
  for (let c = 0; c < cells; c++) {
    const f = (Sre[c] * cw + Sim[c] * sn) * gain;
    const v = f / (1 + Math.abs(f));
    const t = ((v * .5 + .5) * 255 | 0) * 3, o = c * 4;
    d[o] = lut[t]; d[o + 1] = lut[t + 1]; d[o + 2] = lut[t + 2]; d[o + 3] = 255;
  }
  ox.putImageData(img, 0, 0);
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(off, 0, 0, gw * CELL * DPR, gh * CELL * DPR);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  /* the array factor as a polar trace in dB, -30 dB at the centre; the panel hides
     the far side, so the trace is clipped at its top edge */
  const R = Math.min(W, H) * .42;
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, W, panel.offsetTop - 2);
  ctx.clip();
  ctx.beginPath();
  for (let s = 0; s <= AFN; s++) {
    const a = af[s % AFN], db = 20 * Math.log10(Math.max(1e-4, a));
    const rr = Math.max(0, (db + 30) / 30) * R, p = s / AFN * TAU;
    const x = cx + Math.sin(p) * rr, y = cy - Math.cos(p) * rr;
    if (s) ctx.lineTo(x, y); else ctx.moveTo(x, y);
  }
  ctx.strokeStyle = css(pal.beam, .62);
  ctx.lineWidth = 1.2;
  ctx.lineJoin = 'round';
  ctx.stroke();
  ctx.restore();
  /* steer ray */
  ctx.setLineDash([3, 5]);
  ctx.strokeStyle = css(pal.beam, .55);
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + Math.sin(theta) * W * 1.5, cy - Math.cos(theta) * W * 1.5);
  ctx.stroke();
  ctx.setLineDash([]);
  /* emitters, each with a needle showing its drive phase */
  for (let e = 0; e < N; e++) {
    const x = ex[e], y = ey[e], p = phase[e];
    ctx.fillStyle = css(pal.tank, .85);
    ctx.beginPath(); ctx.arc(x, y, 6, 0, TAU); ctx.fill();
    ctx.strokeStyle = css(pal.wave, .9);
    ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.arc(x, y, 4.6, 0, TAU); ctx.stroke();
    ctx.strokeStyle = css(pal.beam, 1);
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + Math.sin(p) * 4.2, y - Math.cos(p) * 4.2); ctx.stroke();
  }
}
let shown = '';
function readout() {
  measure();
  const deg = Math.atan2(Math.sin(theta), Math.cos(theta)) / RAD;
  const s = (deg >= 0 ? '+' : '−') + Math.abs(deg).toFixed(1);
  const b = bwDeg > 170 ? '—' : bwDeg.toFixed(1);
  const g = lobes ? String(lobes) : 'none';
  const key = s + b + g;
  if (key === shown) return;
  shown = key;
  out.steer.textContent = s;
  out.bw.textContent = b;
  out.lobes.textContent = g;
  root.toggleAttribute('data-grating', lobes > 0);
}

/* ── host ── */
let raf = 0, last = 0, seen = true, dead = false, idle = 9, readT = 0, sweepT = 0;
function rebuild() {
  layout();
  steer();
  readout();
  render();
}
function size(w, h) {
  if (w < 2 || h < 2 || (Math.abs(w - W) < .5 && Math.abs(h - H) < .5)) return;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  gw = Math.ceil(W / CELL); gh = Math.ceil(H / CELL);
  off.width = gw; off.height = gh;
  img = ox.createImageData(gw, gh);
  Sre = new Float32Array(gw * gh); Sim = new Float32Array(gw * gh);
  rebuild();
}
function kick() {
  if (dead || raf || calm || !seen || document.hidden) return;
  last = 0;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) return;
  const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
  last = now;
  clock += dt; idle += dt;
  if (idle > 2) { sweepT += dt; target = Math.sin(sweepT * .32) * 52 * RAD; }
  let da = target - theta;
  da = Math.atan2(Math.sin(da), Math.cos(da));
  if (Math.abs(da) > 1e-4) { theta += da * (1 - Math.exp(-dt * 6)); steer(); }
  render();
  readT += dt;
  if (readT > .1) { readT = 0; readout(); }
  raf = requestAnimationFrame(frame);
}
let rz = 0;
const ro = new ResizeObserver(([e]) => {
  const { width, height } = e.contentRect;
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; size(width, height); });
});
ro.observe(cv);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => { calm = mq.matches; if (calm) { theta = target; steer(); readout(); render(); } kick(); };
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => { theme(); render(); });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  cancelAnimationFrame(rz);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}

/* ── input ── */
function aimAt(t) {
  target = t;
  idle = 0;
  sweepT = Math.asin(Math.max(-1, Math.min(1, Math.atan2(Math.sin(t), Math.cos(t)) / (52 * RAD)))) / .32;
  if (calm) { theta = target; steer(); readout(); render(); }
}
stage.addEventListener('pointermove', (e) => {
  const r = stage.getBoundingClientRect();
  aimAt(Math.atan2(e.clientX - r.left - cx, -(e.clientY - r.top - cy)));
});
stage.addEventListener('pointerdown', (e) => {
  const r = stage.getBoundingClientRect();
  aimAt(Math.atan2(e.clientX - r.left - cx, -(e.clientY - r.top - cy)));
});
function setN(n, say) {
  n = Math.max(2, Math.min(16, n));
  if (n === N) return;
  N = n;
  rebuild();
  if (say) live.textContent = N + ' emitters.';
}
function setD(d, say) {
  D = Math.max(.2, Math.min(1.2, Math.round(d * 100) / 100));
  rebuild();
  if (say) live.textContent = 'Spacing ' + D.toFixed(2) + ' wavelengths' + (lobes ? ', ' + lobes + ' grating lobe' + (lobes > 1 ? 's' : '') + ' in view.' : '.');
}
function fresh() {
  seed = 1 + ((Math.random() * 9998) | 0);
  const r = rng(seed);
  geo = (r() * 4) | 0;
  N = [4, 6, 8, 10, 12, 16][(r() * 6) | 0];
  D = Math.round((.35 + r() * .5) * 100) / 100;
  rebuild();
  live.textContent = GEOS[geo] + ' array of ' + N + ', spaced ' + D.toFixed(2) + ' wavelengths.';
}
stage.addEventListener('keydown', (e) => {
  const s = (e.shiftKey ? 10 : 2) * RAD;
  if (e.key === 'ArrowLeft') aimAt(target - s);
  else if (e.key === 'ArrowRight') aimAt(target + s);
  else if (e.key === 'ArrowUp') setD(D + .05, true);
  else if (e.key === 'ArrowDown') setD(D - .05, true);
  else if (e.key === '+' || e.key === '=') setN(N + 1, true);
  else if (e.key === '-' || e.key === '_') setN(N - 1, true);
  else if (e.key === 'Enter' || e.key === ' ') fresh();
  else return;
  e.preventDefault();
  if (e.key.startsWith('Arrow') && e.key.length > 7) live.textContent = 'Steering ' + Math.round(target / RAD) + ' degrees.';
});
steps.forEach((b) => b.addEventListener('click', () => setN(N + +b.dataset.step, true)));
let dT = 0;
dIn.addEventListener('input', () => {
  out.d.textContent = (+dIn.value).toFixed(2) + 'λ';
  clearTimeout(dT);
  dT = setTimeout(() => { if (!root.isConnected) return; setD(+dIn.value, true); }, 60);
});
root.querySelector('.fxg-array__new').addEventListener('click', fresh);

theme();
{
  const r = cv.getBoundingClientRect();
  theta = target = 18 * RAD;
  sweepT = Math.asin(18 / 52) / .32;
  size(r.width, r.height);
}
kick();

css:
.fxg-topo {
  /* Re-theme with these four; the hypsometric tints are mixed from them. */
  --fxg-topo-paper: oklch(0.968 0.016 92);
  --fxg-topo-ink: oklch(0.29 0.03 60);
  --fxg-topo-contour: oklch(0.52 0.09 52);
  --fxg-topo-water: oklch(0.6 0.09 232);

  --fxg-topo-low: color-mix(in oklch, var(--fxg-topo-paper) 74%, oklch(0.76 0.1 132));
  --fxg-topo-mid: color-mix(in oklch, var(--fxg-topo-paper) 70%, oklch(0.76 0.09 80));
  --fxg-topo-high: color-mix(in oklch, var(--fxg-topo-paper) 72%, var(--fxg-topo-contour));
  --fxg-topo-sea: color-mix(in oklch, var(--fxg-topo-paper) 62%, var(--fxg-topo-water));
  --fxg-topo-muted: color-mix(in oklch, var(--fxg-topo-ink) 58%, var(--fxg-topo-paper));
  --fxg-topo-line: color-mix(in oklch, var(--fxg-topo-ink) 15%, transparent);
  --fxg-topo-out: cubic-bezier(.16, 1, .3, 1);
  --fxg-topo-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" "map map" "bar bar";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 10px 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 10 / 9;
  min-block-size: 300px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background: var(--fxg-topo-paper);
  color: var(--fxg-topo-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxg-topo-line);

  & .fxg-topo__head { grid-area: head; min-inline-size: 0; }
  & .fxg-topo__eyebrow {
    margin: 0 0 3px;
    font: 500 10px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .04em;
    color: var(--fxg-topo-contour);
  }
  & .fxg-topo__eyebrow span { font-variant-numeric: tabular-nums; }
  & .fxg-topo__title {
    margin: 0;
    font-size: clamp(17px, 5.6cqi, 24px);
    font-weight: 650;
    line-height: 1.05;
    letter-spacing: .14em;
    text-transform: uppercase;
    text-wrap: balance;
  }
  & .fxg-topo__read {
    grid-area: read;
    display: flex;
    gap: 14px;
    align-self: end;
    margin: 0;
  }
  & .fxg-topo__read div {
    display: grid;
    gap: 3px;
    text-align: end;
    transition: opacity .6s var(--fxg-topo-out) calc(var(--i) * 70ms + 120ms), translate .8s var(--fxg-topo-out) calc(var(--i) * 70ms + 120ms);
    @starting-style { opacity: 0; translate: 0 5px; }
  }
  & .fxg-topo__read dt {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-topo-muted);
  }
  & .fxg-topo__read dd {
    margin: 0;
    min-inline-size: 5ch;
    font: 600 clamp(13px, 4cqi, 16px)/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxg-topo__read small { margin-inline-start: 2px; font-size: .7em; font-weight: 500; color: var(--fxg-topo-muted); }
  & .fxg-topo__read dd[data-bare] small { display: none; }

  & .fxg-topo__map {
    grid-area: map;
    position: relative;
    min-block-size: 0;
    border-radius: 2px;
    background: var(--fxg-topo-low);
    box-shadow: 0 0 0 1px var(--fxg-topo-ink), 0 0 0 4px var(--fxg-topo-paper), 0 0 0 5px var(--fxg-topo-line);
    overflow: hidden;
  }
  & .fxg-topo__cv,
  & .fxg-topo__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxg-topo__cv { display: block; }
  & .fxg-topo__stage {
    z-index: 1;
    outline: none;
    cursor: none;
    touch-action: pan-y;
  }
  & .fxg-topo__stage:focus-visible { box-shadow: inset 0 0 0 2px var(--fxg-topo-water); }

  & .fxg-topo__bar {
    grid-area: bar;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 8px;
  }
  & .fxg-topo__water {
    display: grid;
    grid-template-columns: auto minmax(40px, 1fr) auto;
    align-items: center;
    gap: 7px;
    min-inline-size: 0;
    color: var(--fxg-topo-water);
  }
  & .fxg-topo__water svg {
    inline-size: 16px;
    block-size: 16px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.4;
    stroke-linecap: round;
  }
  & .fxg-topo__water input {
    inline-size: 100%;
    margin: 0;
    accent-color: var(--fxg-topo-water);
    cursor: pointer;
  }
  & .fxg-topo__water input:focus-visible { outline: 2px solid var(--fxg-topo-water); outline-offset: 3px; border-radius: 4px; }
  & .fxg-topo__water output {
    min-inline-size: 5.5ch;
    font: 600 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    text-align: end;
    color: var(--fxg-topo-ink);
  }
  & .fxg-topo__step {
    display: flex;
    margin: 0;
    padding: 2px;
    border: 0;
    border-radius: 7px;
    box-shadow: inset 0 0 0 1px var(--fxg-topo-line);
  }
  & .fxg-topo__step label { position: relative; display: grid; cursor: pointer; }
  & .fxg-topo__step input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & .fxg-topo__step span {
    padding: 5px 7px;
    border-radius: 5px;
    font: 600 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxg-topo-muted);
    transition: background-color .25s var(--fxg-topo-out), color .25s var(--fxg-topo-out), scale .4s var(--fxg-topo-spring);
  }
  & .fxg-topo__step label:hover span { color: var(--fxg-topo-ink); background: color-mix(in oklch, var(--fxg-topo-contour) 12%, transparent); }
  & .fxg-topo__step label:has(:checked) span { background: var(--fxg-topo-contour); color: var(--fxg-topo-paper); }
  & .fxg-topo__step label:has(:active) span { scale: .92; }
  & .fxg-topo__step label:has(:focus-visible) span { outline: 2px solid var(--fxg-topo-water); outline-offset: 1px; }
  & .fxg-topo__new {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    block-size: 30px;
    padding: 0 11px 0 9px;
    border: 0;
    border-radius: 7px;
    background: var(--fxg-topo-ink);
    color: var(--fxg-topo-paper);
    font: 650 11.5px/1 system-ui, sans-serif;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color .25s var(--fxg-topo-out), scale .45s var(--fxg-topo-spring);
  }
  & .fxg-topo__new:hover { background: color-mix(in oklch, var(--fxg-topo-ink) 80%, var(--fxg-topo-contour)); }
  & .fxg-topo__new:active { scale: .94; }
  & .fxg-topo__new:focus-visible { outline: 2px solid var(--fxg-topo-water); outline-offset: 2px; }
  & .fxg-topo__new svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.4;
    stroke-linejoin: round;
  }
  & .fxg-topo__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: 0;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @container (max-width: 350px) {
    & .fxg-topo__new span { display: none; }
    & .fxg-topo__new { padding: 0 9px; }
    & .fxg-topo__read { gap: 10px; }
    & .fxg-topo__title { letter-spacing: .08em; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .fxg-topo {
    & .fxg-topo__read div,
    & .fxg-topo__step span,
    & .fxg-topo__new { transition: none; }
  }
}

js:
/* Survey sheet — a height field from domain-warped fbm (five octaves) with a ridged
   octave laid over the high ground, whose warp drifts slowly so the land breathes.
   Every contour is traced by marching squares in a single pass: each cell finds the
   levels between its lowest and highest corner and emits one or two interpolated
   segments per level (saddles resolved by the cell mean). Index contours (every fifth)
   are heavier and labelled; a label is pinned to a fixed anchor and snaps to the
   nearest segment of its level, so as the terrain moves the labels glide with it. */
const map = root.querySelector('.fxg-topo__map');
const cv = root.querySelector('.fxg-topo__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxg-topo__stage');
const probe = root.querySelector('.fxg-topo__probe');
const live = root.querySelector('p.fxg-topo__sr');
const seaIn = root.querySelector('.fxg-topo__water input');
const steps = [...root.querySelectorAll('.fxg-topo__step input')];
const $ = (n) => root.querySelector('[data-k="' + n + '"]');
const out = { sheet: $('sheet'), name: $('name'), peak: $('peak'), here: $('here'), sea: $('sea') };
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2, CELL = 3, PX_PER_KM = 96 / 2.54 * 4;   /* 1:25 000 -> 4 cm per km */
const A = ['Hollin', 'Scar', 'Tarn', 'Corrie', 'Blea', 'Raven', 'Whin', 'Lang', 'Mardle', 'Hart', 'Swirl', 'Grey', 'Brant', 'Kell'];
const B = ['Edge', 'Fell', 'Crag', 'Knott', 'Pike', 'How', 'Moss', 'Rigg', 'Combe', 'Side'];
let W = 0, H = 0, DPR = 1, gw = 0, gh = 0;
let seed = 27, noise = null, sc = 1, t = 0;
let Z = null, img = null;
let sea = 290, ci = 20, zmin = 0, zmax = 1, peakI = 0;
const off = document.createElement('canvas'), ox = off.getContext('2d');
const lut = new Uint8ClampedArray(256 * 3), wlut = new Uint8ClampedArray(64 * 3);
const pal = {};

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
const mix = (a, b, k) => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
const ZTOP = 1400;
function theme() {
  for (const k of ['paper', 'ink', 'contour', 'water', 'low', 'mid', 'high', 'sea']) pal[k] = rgb('--fxg-topo-' + k);
  /* elevation 0..1400 m: low green, tan mid-slopes, warm high ground, paper summits */
  const stops = [[0, pal.low], [.32, pal.mid], [.66, pal.high], [1, pal.paper]];
  for (let i = 0; i < 256; i++) {
    const e = i / 255;
    let j = 0;
    while (j < stops.length - 2 && e > stops[j + 1][0]) j++;
    const [e0, c0] = stops[j], [e1, c1] = stops[j + 1];
    const c = mix(c0, c1, Math.min(1, Math.max(0, (e - e0) / (e1 - e0))));
    lut[i * 3] = c[0]; lut[i * 3 + 1] = c[1]; lut[i * 3 + 2] = c[2];
  }
  for (let i = 0; i < 64; i++) {
    const c = mix(pal.sea, pal.water, Math.min(1, i / 63 * .55));
    wlut[i * 3] = c[0]; wlut[i * 3 + 1] = c[1]; wlut[i * 3 + 2] = c[2];
  }
}
function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}
function makeNoise(s) {
  const r = rng(s), perm = new Uint8Array(512), gx = new Float32Array(256), gy = new Float32Array(256);
  const p = Array.from({ length: 256 }, (_, i) => i);
  for (let i = 255; i > 0; i--) { const j = (r() * (i + 1)) | 0; const q = p[i]; p[i] = p[j]; p[j] = q; }
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
  for (let i = 0; i < 256; i++) { const a = r() * TAU; gx[i] = Math.cos(a); gy[i] = Math.sin(a); }
  return (x, y) => {
    const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi, X = xi & 255, Y = yi & 255;
    const u = xf * xf * xf * (xf * (xf * 6 - 15) + 10), v = yf * yf * yf * (yf * (yf * 6 - 15) + 10);
    const h00 = perm[perm[X] + Y], h10 = perm[perm[X + 1] + Y], h01 = perm[perm[X] + Y + 1], h11 = perm[perm[X + 1] + Y + 1];
    const a = gx[h00] * xf + gy[h00] * yf, b = gx[h10] * (xf - 1) + gy[h10] * yf;
    const c = gx[h01] * xf + gy[h01] * (yf - 1), d = gx[h11] * (xf - 1) + gy[h11] * (yf - 1);
    return (a + (b - a) * u + (c - a + (a - b - c + d) * u) * v) * 1.4;
  };
}
let shape = null;
function sheet() {
  const r = rng(seed * 101 + 7);
  noise = makeNoise(seed);
  shape = { f: 2.2 + r() * 1.6, ox: r() * 50, oy: r() * 50, ridge: .25 + r() * .3, tilt: (r() - .5) * .5 };
  out.sheet.textContent = seed;
  out.name.textContent = A[(r() * A.length) | 0] + ' ' + B[(r() * B.length) | 0];
}

/* ── the land ── */
function height(u, v) {
  const n = noise;
  const wx = n(u * .55 + 3.1 + t * .045, v * .55 - 1.7) * .85, wy = n(u * .55 - 7.3, v * .55 + 2.9 - t * .038) * .85;
  let x = u + wx + shape.ox, y = v + wy + shape.oy, a = 0, amp = .55, f = 1;
  for (let o = 0; o < 4; o++) { a += n(x * f + o * 17.1, y * f - o * 9.7) * amp; f *= 2.02; amp *= .42; }
  let rd = 0; amp = .5; f = 1.6;
  for (let o = 0; o < 2; o++) { const q = 1 - Math.abs(n(x * f - 41.3, y * f + 23.9)); rd += q * q * amp; f *= 2.1; amp *= .45; }
  const hi = Math.min(1, Math.max(0, a * 1.4 + .45));
  return 430 + (a + shape.tilt * (v - .5 * gh * sc)) * 720 + rd * shape.ridge * 760 * hi * hi;
}
function sample() {
  zmin = Infinity; zmax = -Infinity;
  for (let j = 0; j < gh; j++) {
    for (let i = 0; i < gw; i++) {
      const z = height(i * sc, j * sc), k = j * gw + i;
      Z[k] = z;
      if (z < zmin) zmin = z;
      if (z > zmax) { zmax = z; peakI = k; }
    }
  }
}
function tint() {
  const d = img.data;
  for (let j = 0; j < gh; j++) {
    for (let i = 0; i < gw; i++) {
      const k = j * gw + i, z = Z[k], o = k * 4;
      if (z < sea) {
        const w = Math.min(63, ((sea - z) / 6) | 0) * 3;
        d[o] = wlut[w]; d[o + 1] = wlut[w + 1]; d[o + 2] = wlut[w + 2]; d[o + 3] = 255;
        continue;
      }
      /* hillshade from the north-west, the cartographer's convention */
      const zl = Z[k - (i > 0 ? 1 : 0)], zr = Z[k + (i < gw - 1 ? 1 : 0)], zu = Z[k - (j > 0 ? gw : 0)], zd = Z[k + (j < gh - 1 ? gw : 0)];
      const dx = (zr - zl) / (CELL * 2), dy = (zd - zu) / (CELL * 2);
      const s = Math.max(.82, Math.min(1.08, 1 - (dx + dy) * .045));
      const e = Math.max(0, Math.min(255, (z / ZTOP * 255) | 0)) * 3;
      d[o] = lut[e] * s; d[o + 1] = lut[e + 1] * s; d[o + 2] = lut[e + 2] * s; d[o + 3] = 255;
    }
  }
  ox.putImageData(img, 0, 0);
}

/* ── marching squares, every level in one pass ── */
let plain = new Path2D(), index = new Path2D(), shore = [new Path2D(), new Path2D(), new Path2D()];
let segs = new Map();   /* index level -> flat [x0, y0, x1, y1, ...] for labelling */
let EP = null, EL = null;
function seg(x0, y0, x1, y1) { EP.moveTo(x0, y0); EP.lineTo(x1, y1); if (EL) EL.push(x0, y0, x1, y1); }
function emit(a, b, c, d, x, y, lev) {
  const m = (a > lev ? 1 : 0) | (b > lev ? 2 : 0) | (c > lev ? 4 : 0) | (d > lev ? 8 : 0);
  if (m === 0 || m === 15) return;
  /* crossing points on the top, right, bottom and left edges */
  const tx = x + CELL * (lev - a) / (b - a), ry = y + CELL * (lev - b) / (c - b);
  const bx = x + CELL * (lev - d) / (c - d), ly = y + CELL * (lev - a) / (d - a);
  const X1 = x + CELL, Y1 = y + CELL;
  switch (m) {
    case 1: case 14: seg(tx, y, x, ly); break;
    case 2: case 13: seg(tx, y, X1, ry); break;
    case 3: case 12: seg(x, ly, X1, ry); break;
    case 4: case 11: seg(X1, ry, bx, Y1); break;
    case 6: case 9: seg(tx, y, bx, Y1); break;
    case 7: case 8: seg(x, ly, bx, Y1); break;
    default: {
      /* saddle: the cell mean decides which corners the contour separates */
      if ((m === 5) === ((a + b + c + d) / 4 > lev)) { seg(tx, y, X1, ry); seg(x, ly, bx, Y1); }
      else { seg(tx, y, x, ly); seg(X1, ry, bx, Y1); }
    }
  }
}
function trace() {
  plain = new Path2D(); index = new Path2D(); shore = [new Path2D(), new Path2D(), new Path2D()];
  segs = new Map();
  const wl = [sea, sea - 9, sea - 22], big = ci * 5;
  for (let j = 0; j < gh - 1; j++) {
    for (let i = 0; i < gw - 1; i++) {
      const k = j * gw + i;
      const a = Z[k], b = Z[k + 1], c = Z[k + gw + 1], d = Z[k + gw];
      const lo = Math.min(a, b, c, d), hi = Math.max(a, b, c, d);
      const x = i * CELL, y = j * CELL;
      for (let lev = Math.max(Math.ceil(lo / ci), Math.floor(sea / ci) + 1) * ci; lev < hi; lev += ci) {
        if (lev % big === 0) {
          EP = index; EL = segs.get(lev);
          if (!EL) segs.set(lev, EL = []);
        } else { EP = plain; EL = null; }
        emit(a, b, c, d, x, y, lev);
      }
      EL = null;
      for (let w = 0; w < 3; w++) if (lo < wl[w] && hi > wl[w]) { EP = shore[w]; emit(a, b, c, d, x, y, wl[w]); }
    }
  }
}

/* labels pinned to a fixed lattice of anchors, each taking the nearest index segment */
let labels = [];
function place() {
  labels = [];
  const step = 74;
  for (let ay = step * .55; ay < H - 10; ay += step * .8) {
    for (let ax = step * .5 + ((ay / (step * .8)) | 0) % 2 * step * .5; ax < W - 10; ax += step) {
      let best = 26 * 26, hit = null;
      for (const [lev, list] of segs) {
        for (let q = 0; q < list.length; q += 4) {
          const mx = (list[q] + list[q + 2]) / 2, my = (list[q + 1] + list[q + 3]) / 2;
          const d = (mx - ax) ** 2 + (my - ay) ** 2;
          if (d < best) { best = d; hit = [mx, my, Math.atan2(list[q + 3] - list[q + 1], list[q + 2] - list[q]), lev]; }
        }
      }
      if (!hit || hit[0] < 16 || hit[0] > W - 16 || hit[1] < 10 || hit[1] > H - 10) continue;
      if (labels.some((l) => (l[0] - hit[0]) ** 2 + (l[1] - hit[1]) ** 2 < 40 * 40)) continue;
      if ((hit[0] - (peakI % gw) * CELL) ** 2 + (hit[1] - ((peakI / gw) | 0) * CELL) ** 2 < 34 * 34) continue;
      let a = hit[2];
      if (a > Math.PI / 2) a -= Math.PI; else if (a < -Math.PI / 2) a += Math.PI;
      hit[2] = a;
      labels.push(hit);
    }
  }
}

/* ── drawing ── */
let cursor = null;
const kb = { x: 0, y: 0 };
const marks = [];
function zAt(x, y) {
  const fx = Math.max(0, Math.min(gw - 1.001, x / CELL)), fy = Math.max(0, Math.min(gh - 1.001, y / CELL));
  const i = fx | 0, j = fy | 0, u = fx - i, v = fy - j, k = j * gw + i;
  return (Z[k] * (1 - u) + Z[k + 1] * u) * (1 - v) + (Z[k + gw] * (1 - u) + Z[k + gw + 1] * u) * v;
}
function render() {
  if (!W) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(off, 0, 0, gw * CELL * DPR, gh * CELL * DPR);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  /* waterlines, fading offshore */
  [.8, .45, .25].forEach((a, w) => {
    ctx.strokeStyle = css(pal.water, a);
    ctx.lineWidth = w ? .7 : 1.1;
    ctx.stroke(shore[w]);
  });
  ctx.strokeStyle = css(pal.contour, .6);
  ctx.lineWidth = .65;
  ctx.stroke(plain);
  ctx.strokeStyle = css(pal.contour, .95);
  ctx.lineWidth = 1.25;
  ctx.stroke(index);
  /* index labels, upright, knocked out of the line */
  ctx.font = '600 8.5px ui-monospace, Menlo, monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (const [x, y, a, lev] of labels) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(a);
    const s = String(lev), w = ctx.measureText(s).width + 5;
    ctx.fillStyle = css(lutAt(lev), 1);
    ctx.fillRect(-w / 2, -4.5, w, 9);
    ctx.fillStyle = css(pal.contour, 1);
    ctx.fillText(s, 0, .5);
    ctx.restore();
  }
  /* summit */
  const px = (peakI % gw) * CELL, py = ((peakI / gw) | 0) * CELL;
  ctx.fillStyle = css(pal.ink, 1);
  ctx.beginPath(); ctx.moveTo(px, py - 4.5); ctx.lineTo(px + 4, py + 2.5); ctx.lineTo(px - 4, py + 2.5); ctx.closePath(); ctx.fill();
  ctx.font = 'italic 600 9.5px ui-serif, Georgia, serif';
  ctx.textAlign = px > W - 50 ? 'right' : 'left';
  halo(Math.round(zmax).toLocaleString('en-US'), px + (px > W - 50 ? -7 : 7), py - 1);
  /* benchmarks */
  ctx.font = '600 8.5px ui-monospace, Menlo, monospace';
  for (const m of marks) {
    ctx.strokeStyle = css(pal.ink, 1);
    ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(m.x - 4, m.y); ctx.lineTo(m.x + 4, m.y); ctx.moveTo(m.x, m.y - 4); ctx.lineTo(m.x, m.y + 4); ctx.stroke();
    ctx.beginPath(); ctx.arc(m.x, m.y, 2, 0, TAU); ctx.stroke();
    ctx.textAlign = m.x > W - 60 ? 'right' : 'left';
    halo('BM ' + Math.round(zAt(m.x, m.y)), m.x + (m.x > W - 60 ? -6 : 6), m.y - 7);
  }
  /* scale bar and north */
  const kmPx = PX_PER_KM, sx = 10, sy = H - 12;
  if (kmPx < W - 60) {
    ctx.fillStyle = css(pal.paper, .8);
    ctx.fillRect(sx - 4, sy - 12, kmPx + 30, 18);
    ctx.fillStyle = css(pal.ink, 1);
    ctx.fillRect(sx, sy, kmPx / 2, 2.5);
    ctx.strokeStyle = css(pal.ink, 1);
    ctx.lineWidth = 1;
    ctx.strokeRect(sx + .5, sy + .5, kmPx - 1, 2);
    ctx.font = '600 8px ui-monospace, Menlo, monospace';
    ctx.textAlign = 'left';
    ctx.fillText('0', sx, sy - 6);
    ctx.fillText('1 km', sx + kmPx - 6, sy - 6);
  }
  ctx.fillStyle = css(pal.ink, 1);
  const nx = W - 14, ny = 18;
  ctx.beginPath(); ctx.moveTo(nx, ny - 9); ctx.lineTo(nx + 4, ny + 3); ctx.lineTo(nx, ny); ctx.lineTo(nx - 4, ny + 3); ctx.closePath(); ctx.fill();
  ctx.font = '700 8px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('N', nx, ny + 11);
  /* crosshair */
  const at = stage.matches(':focus-visible') ? kb : cursor;
  if (at) {
    ctx.strokeStyle = css(pal.ink, .85);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(at.x - 12, at.y); ctx.lineTo(at.x - 4, at.y); ctx.moveTo(at.x + 4, at.y); ctx.lineTo(at.x + 12, at.y);
    ctx.moveTo(at.x, at.y - 12); ctx.lineTo(at.x, at.y - 4); ctx.moveTo(at.x, at.y + 4); ctx.lineTo(at.x, at.y + 12);
    ctx.stroke();
  }
}
function halo(s, x, y) {
  ctx.textBaseline = 'middle';
  ctx.lineWidth = 3;
  ctx.strokeStyle = css(pal.paper, .9);
  ctx.strokeText(s, x, y);
  ctx.fillStyle = css(pal.ink, 1);
  ctx.fillText(s, x, y);
}
function lutAt(z) {
  const e = Math.max(0, Math.min(255, (z / ZTOP * 255) | 0)) * 3;
  return [lut[e], lut[e + 1], lut[e + 2]];
}
let shownPeak = -1, shownHere = '';
function readout() {
  const p = Math.round(zmax);
  if (p !== shownPeak) { shownPeak = p; out.peak.textContent = p.toLocaleString('en-US'); }
  const at = stage.matches(':focus-visible') ? kb : cursor;
  const h = at ? (zAt(at.x, at.y) < sea ? 'water' : Math.round(zAt(at.x, at.y)).toLocaleString('en-US')) : '—';
  if (h !== shownHere) {
    shownHere = h;
    out.here.textContent = h;
    out.here.parentElement.toggleAttribute('data-bare', !/\d/.test(h));
  }
}
function full() { sample(); tint(); trace(); place(); render(); readout(); }
/* a new sheet floods its lowest eighth, so every composition opens with lakes */
function flood() {
  const z = Float32Array.from(Z).sort();
  sea = Math.max(0, Math.min(700, Math.round(z[(z.length * .12) | 0] / 10) * 10));
  seaIn.value = sea;
  out.sea.textContent = sea + ' m';
}

/* ── host ── */
let raf = 0, last = 0, seen = true, dead = false, acc = 0;
function size(w, h) {
  if (w < 2 || h < 2 || (Math.abs(w - W) < .5 && Math.abs(h - H) < .5)) return;
  const first = !W, kx = W ? w / W : 1, ky = H ? h / H : 1;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);
  gw = Math.ceil(W / CELL) + 1; gh = Math.ceil(H / CELL) + 1;
  Z = new Float32Array(gw * gh);
  off.width = gw; off.height = gh;
  img = ox.createImageData(gw, gh);
  /* the sheet keeps its features when resized: noise is sampled per sheet width */
  sc = 2.6 / Math.max(gw, gh);
  if (first) { kb.x = W / 2; kb.y = H / 2; sheet(); sample(); flood(); }
  for (const m of marks) { m.x *= kx; m.y *= ky; }
  full();
}
function kick() {
  if (dead || raf || calm || !seen || document.hidden) return;
  last = 0;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) return;
  const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
  last = now;
  acc += dt;
  /* the land moves slowly, so it is resampled at 30 fps */
  if (acc >= 1 / 30) { t += acc * .5; acc = 0; full(); }
  raf = requestAnimationFrame(frame);
}
let rz = 0;
const ro = new ResizeObserver(([e]) => {
  const { width, height } = e.contentRect;
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; size(width, height); });
});
ro.observe(map);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => { calm = mq.matches; kick(); };
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => { theme(); if (W) { tint(); render(); } });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  cancelAnimationFrame(rz);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}

/* ── input ── */
const local = (e) => { const r = stage.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };
stage.addEventListener('pointermove', (e) => { cursor = local(e); readout(); if (calm) render(); });
stage.addEventListener('pointerleave', () => { cursor = null; readout(); render(); });
function bench(x, y) {
  if (marks.length >= 6) marks.shift();
  marks.push({ x, y });
  const z = zAt(x, y);
  live.textContent = z < sea ? 'That point is under water.' : 'Benchmark at ' + Math.round(z) + ' metres.';
  render();
}
stage.addEventListener('pointerdown', (e) => { if (e.button === 0) { const p = local(e); cursor = p; kb.x = p.x; kb.y = p.y; bench(p.x, p.y); } });
function fresh() {
  seed = 10 + ((Math.random() * 990) | 0);
  marks.length = 0;
  sheet();
  sample();
  flood();
  full();
  live.textContent = 'Sheet ' + seed + ', ' + out.name.textContent + '. Summit ' + Math.round(zmax) + ' metres.';
}
stage.addEventListener('keydown', (e) => {
  const s = e.shiftKey ? 24 : 6;
  if (e.key === 'ArrowLeft') kb.x = Math.max(2, kb.x - s);
  else if (e.key === 'ArrowRight') kb.x = Math.min(W - 2, kb.x + s);
  else if (e.key === 'ArrowUp') kb.y = Math.max(2, kb.y - s);
  else if (e.key === 'ArrowDown') kb.y = Math.min(H - 2, kb.y + s);
  else if (e.key === 'Enter' || e.key === ' ') bench(kb.x, kb.y);
  else if (e.key === 'Escape') { if (!marks.length) return; marks.length = 0; live.textContent = 'Benchmarks cleared.'; }
  else if (e.key === 'n' || e.key === 'N') fresh();
  else return;
  e.preventDefault();
  readout();
  render();
});
stage.addEventListener('focus', () => { readout(); render(); });
stage.addEventListener('blur', () => { readout(); render(); });
seaIn.addEventListener('input', () => {
  sea = +seaIn.value;
  out.sea.textContent = sea + ' m';
  tint(); trace(); place(); render(); readout();
});
steps.forEach((r) => r.addEventListener('change', () => {
  if (!r.checked) return;
  ci = +r.value;
  trace(); place(); render();
  live.textContent = 'Contours every ' + ci + ' metres, index every ' + ci * 5 + '.';
}));
root.querySelector('.fxg-topo__new').addEventListener('click', fresh);

theme();
{
  const r = map.getBoundingClientRect();
  size(r.width, r.height);
}
kick();

