.fxg-coral {
  /* Re-theme with these three: the water, the living edge and the oldest ring. */
  --fxg-coral-deep: oklch(0.175 0.018 28);
  --fxg-coral-tip: oklch(0.8 0.13 32);
  --fxg-coral-old: oklch(0.42 0.11 352);

  --fxg-coral-ink: color-mix(in oklch, var(--fxg-coral-tip) 25%, oklch(0.96 0.015 70));
  --fxg-coral-muted: color-mix(in oklch, var(--fxg-coral-ink) 52%, var(--fxg-coral-deep));
  --fxg-coral-line: color-mix(in oklch, var(--fxg-coral-ink) 15%, transparent);
  --fxg-coral-chip: color-mix(in oklch, var(--fxg-coral-deep) 78%, transparent);
  --fxg-coral-out: cubic-bezier(.16, 1, .3, 1);
  --fxg-coral-spring: linear(0, 0.061, 0.212, 0.395, 0.582, 0.755, 0.892, 0.995, 1.061, 1.097, 1.11, 1.105, 1.091, 1.07, 1.05, 1.031, 1.014, 1.003, 0.994, 0.99, 0.988, 0.99, 0.994, 0.998, 1);

  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head read" ". ." "panel panel";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 12px;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 10 / 9;
  min-block-size: 310px;
  max-block-size: 380px;
  padding: 14px;
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  background:
    radial-gradient(90% 70% at 50% 45%, color-mix(in oklch, var(--fxg-coral-deep) 88%, var(--fxg-coral-old)), transparent),
    var(--fxg-coral-deep);
  color: var(--fxg-coral-ink);
  font-family: system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxg-coral-line);

  & .fxg-coral__cv,
  & .fxg-coral__stage {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }
  & .fxg-coral__cv { display: block; }
  & .fxg-coral__stage {
    z-index: 1;
    outline: none;
    touch-action: pan-y;
    border-radius: inherit;
    cursor: copy;
  }
  & .fxg-coral__stage:focus-visible {
    box-shadow: inset 0 0 0 2px var(--fxg-coral-tip), inset 0 0 0 5px color-mix(in oklch, var(--fxg-coral-tip) 22%, transparent);
  }
  & .fxg-coral__head,
  & .fxg-coral__read {
    position: relative;
    z-index: 2;
    margin: 0;
    pointer-events: none;
    text-shadow: 0 0 6px var(--fxg-coral-deep), 0 0 14px var(--fxg-coral-deep);
  }
  & .fxg-coral__head { grid-area: head; min-inline-size: 0; }
  & .fxg-coral__eyebrow {
    margin: 0 0 4px;
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .16em;
    text-transform: uppercase;
    color: var(--fxg-coral-tip);
  }
  & .fxg-coral__title {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin: 0;
    font: 600 clamp(22px, 7.4cqi, 32px)/.95 ui-serif, Georgia, serif;
    letter-spacing: -0.02em;
    text-wrap: balance;
  }
  & .fxg-coral__title span {
    font: 500 10px/1 ui-monospace, Menlo, monospace;
    letter-spacing: 0;
    font-variant-numeric: tabular-nums;
    color: var(--fxg-coral-muted);
  }
  & .fxg-coral__read {
    grid-area: read;
    display: grid;
    gap: 5px;
    align-self: start;
  }
  & .fxg-coral__read div {
    display: flex;
    align-items: baseline;
    justify-content: flex-end;
    gap: 8px;
    transition: opacity .6s var(--fxg-coral-out) calc(var(--i) * 70ms + 150ms), translate .8s var(--fxg-coral-out) calc(var(--i) * 70ms + 150ms);
    @starting-style { opacity: 0; translate: 6px 0; }
  }
  & .fxg-coral__read dt {
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-coral-muted);
  }
  & .fxg-coral__read dd {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    margin: 0;
    min-inline-size: 6ch;
    justify-content: flex-end;
    font: 600 13px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
  }
  & .fxg-coral__read small { font-size: .74em; color: var(--fxg-coral-muted); }
  & .fxg-coral__state { font: 600 11px/1 system-ui, sans-serif; }
  & .fxg-coral__state i {
    inline-size: 6px;
    block-size: 6px;
    border-radius: 50%;
    background: var(--fxg-coral-tip);
    box-shadow: 0 0 0 3px color-mix(in oklch, var(--fxg-coral-tip) 25%, transparent);
    animation: fxg-coral-pulse 1.6s cubic-bezier(.45, 0, .55, 1) infinite;
  }
  &[data-state="mature"] .fxg-coral__state i { background: var(--fxg-coral-ink); box-shadow: none; animation: none; }
  &[data-state="paused"] .fxg-coral__state i { background: var(--fxg-coral-muted); box-shadow: none; animation: none; }

  & .fxg-coral__panel {
    grid-area: panel;
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 8px;
    padding: 7px;
    border-radius: 12px;
    background: var(--fxg-coral-chip);
    backdrop-filter: blur(8px);
    box-shadow: inset 0 0 0 1px var(--fxg-coral-line);
  }
  & .fxg-coral__fold {
    display: grid;
    grid-template-columns: auto minmax(40px, 1fr) auto;
    align-items: center;
    gap: 8px;
    min-inline-size: 0;
    padding-inline-start: 4px;
  }
  & .fxg-coral__name {
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--fxg-coral-muted);
  }
  & .fxg-coral__fold input {
    inline-size: 100%;
    margin: 0;
    accent-color: var(--fxg-coral-tip);
    cursor: pointer;
  }
  & .fxg-coral__fold input:focus-visible { outline: 2px solid var(--fxg-coral-tip); outline-offset: 3px; border-radius: 4px; }
  & .fxg-coral__fold output {
    min-inline-size: 5ch;
    font: 600 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    text-align: end;
  }
  & .fxg-coral__btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    block-size: 30px;
    padding: 0 11px 0 9px;
    border: 0;
    border-radius: 999px;
    background: transparent;
    box-shadow: inset 0 0 0 1px var(--fxg-coral-line);
    color: var(--fxg-coral-ink);
    font: 600 11.5px/1 system-ui, sans-serif;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color .25s var(--fxg-coral-out), scale .45s var(--fxg-coral-spring);
  }
  & .fxg-coral__btn:hover:not(:disabled) { background: color-mix(in oklch, var(--fxg-coral-tip) 14%, transparent); }
  & .fxg-coral__btn:disabled { opacity: .4; cursor: default; }
  & .fxg-coral__btn:active { scale: .94; }
  & .fxg-coral__btn:focus-visible { outline: 2px solid var(--fxg-coral-tip); outline-offset: 2px; }
  & .fxg-coral__btn svg {
    inline-size: 14px;
    block-size: 14px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxg-coral__ic-play { display: none; }
  & .fxg-coral__btn--pause[aria-pressed="true"] .fxg-coral__ic-play { display: inline; }
  & .fxg-coral__btn--pause[aria-pressed="true"] .fxg-coral__ic-pause { display: none; }
  & .fxg-coral__btn--go { background: var(--fxg-coral-tip); box-shadow: none; color: var(--fxg-coral-deep); }
  & .fxg-coral__btn--go:hover { background: color-mix(in oklch, var(--fxg-coral-tip) 82%, white); }
  & .fxg-coral__sr {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @container (max-width: 360px) {
    & .fxg-coral__btn span { display: none; }
    & .fxg-coral__btn { padding: 0 8px; }
  }
}

@keyframes fxg-coral-pulse {
  50% { scale: .6; opacity: .55; }
}

@media (prefers-reduced-motion: reduce) {
  .fxg-coral {
    & .fxg-coral__read div,
    & .fxg-coral__btn { transition: none; }
    & .fxg-coral__state i { animation: none; }
  }
}

js:
/* Reef — differential growth (after Anders Hoff's "inconvergent" studies and
   Jason Webb's write-ups). Each colony is a closed curve stored as a linked list, so
   a node can be inserted between two others in O(1). Every step, a node is
   (1) pulled toward its two neighbours when an edge is longer than the rest length,
   (2) pulled toward their midpoint, which smooths kinks, and (3) pushed away from
   every other node within the fold radius, found through a uniform grid. Edges
   longer than 1.6 rest lengths split, and a few random edges split each step (more
   where the pointer feeds), so the curve keeps gaining length it has no room for
   and buckles into folds. The outline is stamped every half second as a ring. */
const cv = root.querySelector('.fxg-coral__cv');
const ctx = cv.getContext('2d');
const stage = root.querySelector('.fxg-coral__stage');
const probe = root.querySelector('.fxg-coral__probe');
const panel = root.querySelector('.fxg-coral__panel');
const live = root.querySelector('p.fxg-coral__sr');
const foldIn = root.querySelector('.fxg-coral__fold input');
const btnPause = root.querySelector('.fxg-coral__btn--pause');
const $ = (n) => root.querySelector('[data-k="' + n + '"]');
const out = { seed: $('seed'), nodes: $('nodes'), len: $('len'), state: $('state'), fold: $('fold') };
const mq = matchMedia('(prefers-reduced-motion: reduce)');
let calm = mq.matches;

const TAU = Math.PI * 2, MAXN = 1700, MM = 25.4 / 96;
const X = new Float32Array(MAXN), Y = new Float32Array(MAXN), FX = new Float32Array(MAXN), FY = new Float32Array(MAXN);
const NXT = new Int32Array(MAXN), PRV = new Int32Array(MAXN), cnext = new Int32Array(MAXN);
let n = 0, heads = [];
let W = 0, H = 0, DPR = 1, fold = 11, seed = 1953, paused = false, mature = false;
let cells = null, gcols = 0, grows = 0;
let feed = null;
const kb = { x: 0, y: 0 };
const hist = document.createElement('canvas'), hx = hist.getContext('2d');
const pal = {};

const sw = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
function rgb(prop) {
  probe.style.color = 'var(' + prop + ')';
  sw.clearRect(0, 0, 1, 1);
  sw.fillStyle = '#000';
  sw.fillStyle = getComputedStyle(probe).color;
  sw.fillRect(0, 0, 1, 1);
  const d = sw.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
const css = (c, a) => 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a + ')';
const mix = (a, b, k) => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
function theme() { pal.deep = rgb('--fxg-coral-deep'); pal.tip = rgb('--fxg-coral-tip'); pal.old = rgb('--fxg-coral-old'); pal.ink = rgb('--fxg-coral-ink'); }
function rng(s) {
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let q = Math.imul(s ^ (s >>> 15), 1 | s);
    q = (q + Math.imul(q ^ (q >>> 7), 61 | q)) ^ q;
    return ((q ^ (q >>> 14)) >>> 0) / 4294967296;
  };
}
let rnd = rng(seed);

/* ── the dish ── */
let bx0 = 0, by0 = 0, bx1 = 0, by1 = 0;
function bounds() { bx0 = 12; by0 = 12; bx1 = W - 12; by1 = (panel.offsetTop || H) - 10; }
function colony(cx, cy, r0) {
  const m = Math.max(10, Math.round(TAU * r0 / (fold * .45)));
  if (n + m > MAXN - 8) return false;
  const first = n;
  for (let i = 0; i < m; i++) {
    const a = i / m * TAU, j = 1 + (rnd() - .5) * .12;
    const k = n++;
    X[k] = cx + Math.cos(a) * r0 * j; Y[k] = cy + Math.sin(a) * r0 * j;
    NXT[k] = i === m - 1 ? first : k + 1;
    PRV[k] = i === 0 ? first + m - 1 : k - 1;
  }
  heads.push(first);
  return true;
}
function sow() {
  rnd = rng(seed);
  n = 0; heads = []; mature = false; age = 0; stampT = 0;
  hx.setTransform(1, 0, 0, 1, 0, 0);
  hx.clearRect(0, 0, hist.width, hist.height);
  const want = 1 + ((rnd() * 3) | 0), placed = [];
  for (let t = 0; t < 200 && placed.length < want; t++) {
    /* the first colony starts near the middle of the dish, the others wherever there is room */
    const k = placed.length ? 1 : .3;
    const x = (bx0 + bx1) / 2 + (rnd() - .5) * (bx1 - bx0 - 80) * k, y = (by0 + by1) / 2 + 10 + (rnd() - .5) * (by1 - by0 - 90) * k;
    if (placed.some((p) => Math.hypot(p[0] - x, p[1] - y) < Math.min(W, H) * .32)) continue;
    placed.push([x, y]);
    colony(x, y, 9 + rnd() * 6);
  }
  out.seed.textContent = 'No. ' + String(seed).padStart(4, '0');
  state();
}
function insertAfter(i) {
  if (n >= MAXN) return -1;
  const j = NXT[i], k = n++;
  X[k] = (X[i] + X[j]) / 2 + (rnd() - .5) * .3;
  Y[k] = (Y[i] + Y[j]) / 2 + (rnd() - .5) * .3;
  NXT[k] = j; PRV[k] = i; NXT[i] = k; PRV[j] = k;
  return k;
}

/* ── one step of the dynamics ── */
let breath = 0;
function step(grow) {
  /* a mature reef keeps breathing: its fold radius swells and eases by half a pixel */
  const R = fold + (mature ? Math.sin(breath) * .55 : 0), R2 = R * R, rest = R * .45, split = rest * 1.6;
  gcols = Math.ceil(W / R) + 1; grows = Math.ceil(H / R) + 1;
  if (!cells || cells.length < gcols * grows) cells = new Int32Array(gcols * grows);
  cells.fill(-1);
  for (let i = 0; i < n; i++) {
    const c = Math.min(grows - 1, Math.max(0, (Y[i] / R) | 0)) * gcols + Math.min(gcols - 1, Math.max(0, (X[i] / R) | 0));
    cnext[i] = cells[c]; cells[c] = i;
  }
  for (let i = 0; i < n; i++) {
    const x = X[i], y = Y[i], p = PRV[i], q = NXT[i];
    let fx = 0, fy = 0;
    /* springs to both neighbours, only when stretched */
    for (const j of [p, q]) {
      const dx = X[j] - x, dy = Y[j] - y, d = Math.sqrt(dx * dx + dy * dy) || 1e-6;
      if (d > rest) { const f = (d - rest) / d * .35; fx += dx * f; fy += dy * f; }
    }
    /* toward the neighbours' midpoint: smoothing */
    fx += ((X[p] + X[q]) / 2 - x) * .22;
    fy += ((Y[p] + Y[q]) / 2 - y) * .22;
    /* repulsion from everything else in reach */
    const ci = (x / R) | 0, cj = (y / R) | 0;
    for (let b = Math.max(0, cj - 1); b <= Math.min(grows - 1, cj + 1); b++) {
      for (let a = Math.max(0, ci - 1); a <= Math.min(gcols - 1, ci + 1); a++) {
        for (let j = cells[b * gcols + a]; j >= 0; j = cnext[j]) {
          if (j === i || j === p || j === q) continue;
          const dx = x - X[j], dy = y - Y[j], d2 = dx * dx + dy * dy;
          if (d2 >= R2 || d2 < 1e-6) continue;
          const d = Math.sqrt(d2), f = (R - d) / R / d * .9;
          fx += dx * f; fy += dy * f;
        }
      }
    }
    /* the feeder draws nearby growth a little toward it */
    if (feed) {
      const dx = feed.x - x, dy = feed.y - y, d2 = dx * dx + dy * dy;
      if (d2 < 90 * 90) { fx += dx * .006; fy += dy * .006; }
    }
    /* the dish wall */
    if (x < bx0) fx += (bx0 - x) * .5; else if (x > bx1) fx += (bx1 - x) * .5;
    if (y < by0) fy += (by0 - y) * .5; else if (y > by1) fy += (by1 - y) * .5;
    const m = Math.hypot(fx, fy);
    if (m > 1.6) { fx *= 1.6 / m; fy *= 1.6 / m; }
    FX[i] = fx; FY[i] = fy;
  }
  for (let i = 0; i < n; i++) { X[i] += FX[i]; Y[i] += FY[i]; }
  if (!grow || mature) return;
  /* long edges split; then a few random edges split, many more near the feeder */
  const n0 = n;
  for (let i = 0; i < n0 && n < MAXN; i++) {
    const j = NXT[i];
    if ((X[j] - X[i]) ** 2 + (Y[j] - Y[i]) ** 2 > split * split) insertAfter(i);
  }
  const tries = feed ? 10 : 3;
  for (let t = 0; t < tries && n < MAXN; t++) {
    const i = (rnd() * n) | 0;
    let w = .3;
    if (feed) { const dx = feed.x - X[i], dy = feed.y - Y[i]; w += 2.4 * Math.exp(-(dx * dx + dy * dy) / (2 * 55 * 55)); }
    if (rnd() < w / 2.7) insertAfter(i);
  }
  if (n >= MAXN - 2) { mature = true; state(); live.textContent = 'The reef has reached ' + n.toLocaleString('en-US') + ' nodes and stopped growing.'; }
}

/* ── drawing ── */
let age = 0, stampT = 0;
function outline(g) {
  g.beginPath();
  for (const h of heads) {
    let i = h, guard = 0;
    g.moveTo(X[i], Y[i]);
    do { i = NXT[i]; g.lineTo(X[i], Y[i]); } while (i !== h && ++guard < MAXN);
    g.closePath();
  }
}
function stamp() {
  hx.setTransform(DPR, 0, 0, DPR, 0, 0);
  hx.lineJoin = 'round';
  const k = Math.min(1, n / MAXN);
  hx.strokeStyle = css(mix(pal.old, pal.tip, k * .8), .38);
  hx.lineWidth = .8;
  outline(hx);
  hx.stroke();
}
function render() {
  if (!W) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, cv.width, cv.height);
  ctx.drawImage(hist, 0, 0);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  ctx.lineJoin = 'round';
  outline(ctx);
  ctx.fillStyle = css(pal.tip, .06);
  ctx.fill('evenodd');
  ctx.shadowColor = css(pal.tip, .6);
  ctx.shadowBlur = calm ? 0 : 7;
  ctx.strokeStyle = css(pal.tip, 1);
  ctx.lineWidth = 1.6;
  ctx.stroke();
  ctx.shadowBlur = 0;
  const at = stage.matches(':focus-visible') ? kb : feed;
  if (at) {
    ctx.strokeStyle = css(pal.ink, .75);
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(at.x, at.y, 3, 0, TAU); ctx.stroke();
    ctx.setLineDash([2, 4]);
    ctx.strokeStyle = css(pal.ink, .3);
    ctx.beginPath(); ctx.arc(at.x, at.y, 55, 0, TAU); ctx.stroke();
    ctx.setLineDash([]);
  }
}
function length() {
  let L = 0;
  for (let i = 0; i < n; i++) { const j = NXT[i]; L += Math.hypot(X[j] - X[i], Y[j] - Y[i]); }
  return L;
}
function readout() {
  out.nodes.textContent = n.toLocaleString('en-US');
  out.len.textContent = (length() * MM / 1000).toFixed(2);
}
function state() {
  const s = paused ? 'paused' : mature ? 'mature' : 'growing';
  root.dataset.state = s;
  out.state.textContent = s[0].toUpperCase() + s.slice(1);
}

/* ── host ── */
let raf = 0, last = 0, seen = true, dead = false, readT = 0;
/* reduced motion: the reef is grown off-screen to a settled size and shown once */
function grownStill() {
  for (let s = 0; s < 2600 && n < MAXN * .7; s++) { step(true); if (s % 60 === 0) stamp(); }
  for (let s = 0; s < 30; s++) step(false);
  mature = true;
  render(); readout(); state();
}
function size(w, h) {
  if (w < 2 || h < 2 || (Math.abs(w - W) < .5 && Math.abs(h - H) < .5)) return;
  const first = !W, kx = W ? w / W : 1, ky = H ? h / H : 1;
  W = w; H = h;
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = hist.width = Math.round(W * DPR);
  cv.height = hist.height = Math.round(H * DPR);
  bounds();
  kb.x = W / 2; kb.y = H / 2;
  if (first) {
    sow();
    if (calm) { grownStill(); return; }
    for (let s = 0; s < 460; s++) { step(true); if (s % 30 === 0) stamp(); }
  } else {
    for (let i = 0; i < n; i++) { X[i] *= kx; Y[i] *= ky; }
    stamp();
  }
  render();
  readout();
}
function kick() {
  if (dead || raf || calm || !seen || document.hidden) return;
  last = 0;
  raf = requestAnimationFrame(frame);
}
function frame(now) {
  if (!root.isConnected) return teardown();
  raf = 0;
  if (!seen || document.hidden || calm) return;
  const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;
  last = now;
  if (!paused) {
    breath += dt * .9;
    step(true); step(true);
    age += dt;
    stampT += dt;
    if (stampT > .5 && !mature) { stampT = 0; stamp(); }
  }
  render();
  readT += dt;
  if (readT > .25) { readT = 0; readout(); }
  raf = requestAnimationFrame(frame);
}
let rz = 0;
const ro = new ResizeObserver(([e]) => {
  const { width, height } = e.contentRect;
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; size(width, height); });
});
ro.observe(cv);
const io = new IntersectionObserver(([e]) => { seen = e.isIntersecting; kick(); }, { rootMargin: '80px' });
io.observe(root);
const onVis = () => kick();
document.addEventListener('visibilitychange', onVis);
const onMq = () => { calm = mq.matches; calmUI(); if (calm) { if (!mature) grownStill(); else render(); } kick(); };
mq.addEventListener('change', onMq);
const mo = new MutationObserver(() => { theme(); render(); });
mo.observe(root, { attributes: true, attributeFilter: ['style', 'class'] });
const dog = setInterval(() => { if (!root.isConnected) return teardown(); }, 2000);
function teardown() {
  if (dead) return;
  dead = true;
  cancelAnimationFrame(raf);
  cancelAnimationFrame(rz);
  clearInterval(dog);
  ro.disconnect(); io.disconnect(); mo.disconnect();
  document.removeEventListener('visibilitychange', onVis);
  mq.removeEventListener('change', onMq);
}

/* ── input ── */
const local = (e) => { const r = stage.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };
stage.addEventListener('pointermove', (e) => { feed = local(e); if (calm) render(); });
stage.addEventListener('pointerleave', () => { feed = null; if (calm) render(); });
function plant(x, y) {
  if (heads.length >= 6 || n > MAXN - 60) { live.textContent = 'No room for another colony.'; return; }
  if (x < bx0 + 10 || x > bx1 - 10 || y < by0 + 10 || y > by1 - 10) return;
  if (mature) { mature = false; }
  colony(x, y, 8);
  state();
  live.textContent = 'Colony ' + heads.length + ' planted.';
  if (calm) grownStill(); else render();
}
stage.addEventListener('pointerdown', (e) => { if (e.button === 0) { const p = local(e); plant(p.x, p.y); } });
function fresh() {
  seed = 1 + ((Math.random() * 9998) | 0);
  sow();
  live.textContent = 'New dish, number ' + seed + ', with ' + heads.length + (heads.length > 1 ? ' colonies.' : ' colony.');
  if (calm) grownStill(); else { render(); readout(); }
}
function togglePause() {
  paused = !paused;
  btnPause.setAttribute('aria-pressed', String(paused));
  btnPause.querySelector('span').textContent = paused ? 'Grow' : 'Pause';
  state();
  live.textContent = paused ? 'Growth paused.' : 'Growing again.';
}
stage.addEventListener('keydown', (e) => {
  const s = e.shiftKey ? 24 : 8;
  if (e.key === 'ArrowLeft') kb.x = Math.max(bx0, kb.x - s);
  else if (e.key === 'ArrowRight') kb.x = Math.min(bx1, kb.x + s);
  else if (e.key === 'ArrowUp') kb.y = Math.max(by0, kb.y - s);
  else if (e.key === 'ArrowDown') kb.y = Math.min(by1, kb.y + s);
  else if (e.key === 'Enter') plant(kb.x, kb.y);
  else if (e.key === ' ') { if (!calm) togglePause(); }
  else if (e.key === 'n' || e.key === 'N') fresh();
  else return;
  e.preventDefault();
  if (e.key.startsWith('Arrow')) feed = { x: kb.x, y: kb.y };
  if (calm) render();
});
stage.addEventListener('blur', () => { feed = null; if (calm) render(); });
btnPause.addEventListener('click', togglePause);
root.querySelector('.fxg-coral__btn--go').addEventListener('click', fresh);
foldIn.addEventListener('input', () => {
  fold = +foldIn.value;
  out.fold.textContent = fold + ' px';
  if (calm) { for (let s = 0; s < 40; s++) step(false); render(); }
});

/* reduced motion: the reef is shown grown and still, so there is nothing to pause */
function calmUI() { btnPause.disabled = calm; if (calm && paused) togglePause(); }
theme();
calmUI();
{
  const r = cv.getBoundingClientRect();
  size(r.width, r.height);
}
kick();
